quests[11617] = { id = 11617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihre Flucht vereiteln", description = "Ich bin mir sicher, dass Ihr diese blauen und weißen Plattformen, die über dem Steinbruch schweben, gesehen habt. Sie dienen Magiertötern als Transportmittel für ihre Truppenlandungen und nun werden sie mit Artefakten und Fragmenten unserer Statuen beladen.\n\nWir müssen sie aufhalten, bevor sie den Steinbruch verlassen.\n\nDie kleinen Kreaturen, die im Steinbruch herumgraben, tragen Sprengstoff bei sich. Nehmt ihnen das Zeugs ab und zerstört die drei schwebenden Plattformen. Der Anführer hält von einer vierten, gelandeten Plattform aus Ausschau, doch um ihn werden wir uns erst später kümmern.", sourceObjective = "Etaruk möchte, dass ihr die nördliche Plattform, die östliche Plattform und die westliche Plattform zerstört. Er befindet sich außerhalb des Froststeinbruchs.", completion = "Für die Magierjäger wird es schwerer, den Steinbruch zu plündern und unsere Artefakte zu stehlen, als gedacht. Mit Eurer Hilfe, werden wir den Steinbruch zurückerobern und die Dinge wieder richtig stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11618] = { id = 11618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung trifft ein...", description = "<Höllschrei schüttelt seinen Kopf.>\n\nIhr habt es vielleicht nicht bemerkt, aber wir versuchen hier, einen Krieg zu gewinnen, {race}. Ich benötige alle verfügbaren Soldaten an den Brandherden des Konflikts. Das bedeutet, dass wir keine echten Soldaten für kleinere Übergriffe abziehen können.\n\n<Höllschrei hält inne und denkt nach.>\n\nWenn Barthus Verstärkung am Hof will...\n\n<Höllschrei klatscht seine Hände zusammen.>\n\n...wird er sie bekommen! Meldet Euch bei Barthus' Auftragsmördern, die sich westlich von hier bei den Höfen aufhalten. Lasst sie wissen, dass Verstärkung eingetroffen ist.", sourceObjective = "Macht Schattenpirscher Ickoris ausfindig. Er befindet sich bei den Höfen des Kriegshymnenklans westlich der Kriegshymnenfeste.", completion = "Das ist alles? Ein {race}? Höllschrei hat nur einen einzigen {class} geschickt?\n\nWenn ich noch eine Kinnlade hätte, wäre sie jetzt auf den Boden gefallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11619] = { id = 11619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gamel der Grausame", description = "Mein eigener Vater wurde vom Anführer dieser Plünderer getötet - man nennt ihn Gamel den Grausamen. Er hat das Innere der Höhle an diesem Strand zu seinem Heim gemacht.\n\nIhr habt Euch bereits um seine Männer gekümmert. Führt zu Ende, was Ihr angefangen habt, {name}. Rächt meinen Vater und ich werde mit Euch meinen restlichen Besitz teilen.", sourceObjective = "Karuk möchte, dass Ihr Gamel den Grausamen tötet. Er befindet sich am Strand der Peitschennarbe.", progress = "Habt Ihr Gamel besiegt, {class}?", completion = "Ihr habt es vollbracht, {name}! Die Geister der getöteten Tuskarr können nun in Frieden ruhen - ihr Tod wurde gerächt!", sourceObjectiveStatus = "unverified-source-field" }
quests[11620] = { id = 11620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eines Vaters Wort", description = "Es gibt jemanden, der ein wenig Licht ins Dunkel bringen könnte, {race}. Man munkelt, dass die Kvaldir im Tempel in der westlichen Gegend des Strandes eine Nagapriesterin am Leben gelassen haben.\n\nSie wird ohne Zweifel gute Gründe haben, ihre ungebetenen Kvaldirgäste zu hassen. Vielleicht erwartet mein Vater, dass sie auf irgendeine Weise mit Euch kooperieren wird.", sourceObjective = "Geht zum Schrein der Schuppen auf dem Strand der Peitschennarbe und haltet dort nach Veehja Ausschau.", completion = "Hsssssssssssss! Seid Ihr hier, um Euch über mich lustig zu machen, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[11621] = { id = 11621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leviroths Tafel", description = "Ihr seht Euch die Radierungen auf der Tafel genau an und sucht nach verständlichen Textpassagen. Endlich findet Ihr folgendes Fragment:\n\n\"Für ihn, der in den dunkelsten Gewässern haust, werden die Söhne des Nebels Tausende von Seelen fordern, bis schließlich sein Abgesandter erwacht.\"\n\nKaruk könnte an dieser Information interessiert sein.", sourceObjective = "Kehrt zu Karuk zurück und überbringt ihm die Information, die Ihr auf der Tafel gefunden habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11622] = { id = 11622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Peitschennarbe", description = "Es gibt jemanden, der ein wenig Licht ins Dunkel bringen könnte, {race}. Man munkelt, dass die Kvaldir eine Handvoll von Nagapriesterinnen im Inneren des Tempels am Leben gelassen haben.\n\nDie Hohepriesterin Veehja wird zweifellos gute Gründe haben, ihre ungebetenen Kvaldirgäste zu hassen. Vielleicht kann sie Euch mehr darüber sagen, was die Schrift auf der Tafel zu bedeuten hat.", sourceObjective = "Sucht in den Ruinen der Peitschennarbe in der Boreanischen Tundra nach Veehja und sprecht mit ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[11623] = { id = 11623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Besuch beim Kurator", description = "Der Anführer der Magierjägertruppen ist eine gefürchtete Kreatur namens Kurator Insivius. Mein Volk hat seit Generationen zu Land und zu Wasser unzählige Biester gejagt, doch ich habe noch nie etwas gesehen, das diesem Kurator auf irgendeine Art und Weise ähnelt.\n\nEr ist mit einer der fliegenden Scheiben am oberen Rand des Steinbruchs gelandet und überwacht von dort aus die Operation. {name}, ich kann nur glauben, dass die Ahnen selbst Euch zu mir geschickt haben, um mir dabei zu helfen, diese Magierjäger ein für alle Mal aus diesem Steinbruch zu verjagen.", sourceObjective = "Etaruk am äußeren Rand des Frostfelssteinbruchs möchte, dass Ihr Kurator Insivius tötet.", completion = "Der Kurator und seine Männer müssen gedacht haben, dass sie bei Plünderungen im Steinbruch leichtes Spiel haben würden, doch Ihr habt sie eines Besseren belehrt, {name}. Ich bin Euch für Eure Hilfe zutiefst dankbar und bin mir sicher, dass die Ahnen weiterhin auf Euch Acht geben werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[11624] = { id = 11624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Himmel wird es wissen", description = "Ich muss herausfinden, was meinem Meister Scharfseher Grimmläufer zugestoßen ist!\n\nKurz zuvor war er dabei, die Magnatauren im nahegelegenen Magmut zu beobachten. Doch gerade ist einer seiner Grunzer zurückgekehrt und meint, dass der Trupp zerschlagen wurde und der Weissager in die Tiefen dieses Ortes verschleppt wurde.\n\nBevor ich Euch jedoch auf eine Selbstmordmission schicke, möchte ich die Geister befragen, um mehr zu erfahren.\n\nEs gibt ein Luftelementar namens Imperean in den westlich gelegenen Ruinen von Eldra'nath. Es ist weise und könnte Euch vielleicht die Informationen geben, nach denen Ihr sucht.", sourceObjective = "Sprecht mit Imperean in den Ruinen von Eldra'nath.", completion = "Wie töricht von Euch, hierher zu kommen, kleiner {race}.\n\nWonach verlangt es Euch?", sourceObjectiveStatus = "unverified-source-field" }
quests[11625] = { id = 11625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Dreizack von Naz'jan", description = "Fünfhundert Jahre ist es her, seit Azshara ihm die Tiefen des Gewässers unter uns zum Kerker machte. Doch nun trachten die Barbaren danach, das Werk unserer Königin zunichtezumachen!\n\nSie haben unsere Stadt erobert und damit begonnen, meine Brüder ihrem dunklen Gott zu opfern! Als alle Naga schon geopfert waren, da griffen sie nach den Tuskarr – ihre Geister werden keine Ruhe finden!\n\nIch werde Euch helfen, denn für mich wäre es, als trinke ich einen großen Schluck, um meinen Durst nach Rache zu stillen. Ihr Anführer Ragnar hält sich im Nordosten des Gebietes der Peitschennarbe auf. Er nennt einen goldenen Dreizack sein Eigen. Bringt ihn mir!", sourceObjective = "Veehja möchte, dass Ihr zur nordöstlichsten Ecke der Ruinen der Peitschennarbe geht und nach Ragnar Drakkarlund sucht. Tötet ihn und nehmt ihm den Dreizack von Naz'jan ab.", progress = "Habt Ihr den Dreizack bei Euch?", completion = "Aussssssgezeichnet! Wir werden Kvaldirs Bestien töten! Ich werde dieser Brut schon zeigen, was passiert, wenn man sich mit einer Priesterin der Schuppe anlegt!", sourceObjectiveStatus = "unverified-source-field" }
quests[11626] = { id = 11626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Abgesandte", description = "Raj Naz'jan war der Imperator der Peitschennarbe, als Leviroth eingekerkert wurde. Azshara selbst segnete seinen Dreizack, so dass er die Bestie töten würde, sollte sie jemals entkommen.\n\nNun tragt Ihr ihn, {race}. So sehr es mich anwidert, doch ich werde meine Rache an diesen barbarischen Riesenmännern haben.\n\nNehmt den Dreizack und begebt Euch nördlich der Ruinen der Peitschennarbe in die Tiefen. Leviroth befindet sich unterhalb des Eisberges, der den Ruinen am nächsten ist.\n\nStreckt ihn nieder und treibt den Dreizack tief in sein Fleisch! Kehrt anschließend zu dem, der Euch ausgesandt hat, zurück. Ich möchte Euch nicht wieder sehen.", sourceObjective = "Sucht nach Leviroth unter einem Eisberg, der gleich nördlich der Ruinen der Peitschennarbe im Wasser treibt. Erschlagt ihn mit dem Dreizack von Naz'jan und kehrt zu Karuk in die Gegend nördlich des Strands der Peitschennarbe zurück.", completion = "Die Geister meines Volkes können nun in Frieden ruhen. Ihr habt mir dabei geholfen, meinem Vater Ehre zu erweisen... Vielleicht werde ich eines Tages genauso stark sein wie Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[11627] = { id = 11627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siedepunkt", description = "Ihr seid also auf Informationen aus: Aufenthaltsort und Zustand Eures 'Weissagers'. Um seine eigenen Probleme vorauszusehen, hat es wohl nicht ganz gereicht.\n\nNichtsdestotrotz werde ich Euch helfen, dieses Wissen zu erlangen. Doch zuerst werdet Ihr etwas für mich tun.\n\nZweifellos habt Ihr den Krieg zwischen Feuer und Wasser im Süden gesehen. Brodler bringt Neers Teich unablässig zum Kochen und die zwei kämpfen nun schon seit einer Ewigkeit.\n\nBegebt Euch zur Kohlschwarzen Anhöhe und zum Kochenden Teich und bringt die beiden dazu, dass sie mit ihrem Gezanke aufhören.", sourceObjective = "Imperean möchte, dass Ihr Brodler und Neer unterwerft. Kehrt zu ihm zurück, sobald sie sich Euch ergeben haben. Er befindet sich in den Ruinen von Eldra'nath.", completion = "Es freut mich, obwohl sie zweifellos ein wenig weiterstreiten werden.\n\nEs gibt jedoch noch etwas anderes, das Ihr erledigen müsst, bevor Ihr zu Eurer Geisterflüsterin zurückkehren könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11628] = { id = 11628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Mantel der Geißel", description = "Im Nordosten zeichnet sich die Tempelstadt En'kilah, Sitz der Geißel in der Boreanischen Tundra, drohend am Horizont ab. Aus dem Schutz ihrer Mauern heraus hat der Kommandant der Geißel seine Neruber ausgesandt, um uns einzukesseln.\n\nWeiterhin defensiv zu bleiben, wäre der Untergang für meine Leute, doch meine Ratgeber unterscheiden sich in ihren Strategien. Durm würde blindlings hineinstürmen, während die Weise Aeire ein heimliches Vorgehen vorziehen würde.\n\nDie Tempelstadt hat das Land und die Kreaturen rings um sich verdorben. Aeire glaubt, dass die Pelze der verseuchten Mammuts als Mantel dienen könnten, mit dessen Hilfe ein Eindringling versteckt werden könnte.", sourceObjective = "Häuptling Orkan in Taunka'le möchte, dass Ihr ihm 5 verseuchte Mammutpelze bringt.", progress = "Habt Ihr mir die Mammutpelze gebracht?", completion = "So sehr ich mich auch dagegen sträube, solche von Krankheiten nur so strotzenden Dinger ins Dorf zu bringen, sie könnten uns doch einen Vorteil gegenüber unseren Feinden verschaffen.\n\n<Der Häuptling deutet auf die Weise Aeire und winkt die Pelze mit Verachtung von sich.>\n\nWährend sie die Pelze vorbereitet, müssen wir etwas Anderes herstellen - den Umhang.", sourceObjectiveStatus = "unverified-source-field" }
quests[11629] = { id = 11629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zur Geisterflüsterin zurück", description = "Ihr habt getan, was von Euch verlangt wurde, und nun gebe ich Euch, wonach es Euch verlangt.\n\nLiefert diese Urluft bei der Geisterflüsterin im Außenposten Bor'gorok ab. Wenn sie weise ist, wird sie ein Ritual kennen, mit dem Ihr die Informationen, nach denen Ihr sucht, bekommen könnt.", sourceObjective = "Liefert Impereans Urluft bei der Geisterflüsterin Fletschfang im Außenposten Bor'gorok ab.", progress = "{name}, Ihr seid zurückgekehrt. Was habt Ihr erfahren?\n\nWas ist das für ein Geräusch?", completion = "Imperean hat Euch seine eigene Urluft gegeben? Ich kann seine heulenden Winde hören!\n\nIch kenne ein Ritual, für das wir es benutzen können. Wir müssen uns beeilen, bevor seine Urluft sich selbst in Stücke reißt!", sourceObjectiveStatus = "unverified-source-field" }
quests[11630] = { id = 11630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlechte Erde", description = "Die Weise Aeire glaubt, dass, falls wir die Bälge mit der verdorbenen Erde außerhalb der Tempelstadt härten, sie daraus einen Mantel herstellen könnte, durch den die meisten Diener der Geißel Eure Gegenwart ignorieren werden. Ihr solltet dann gut dazu passen, meint sie.\n\nSie wird besser Recht haben. Es ist die einzige Chance, die wir haben, um Informationen zu sammeln und einen Gegenschlag zu planen.\n\nIhr solltet die Erde, die sie benötigt, in den Gegenden südlich und westlich der Festung finden. Bringt sie zu mir, wenn Ihr genug gesammelt habt.", sourceObjective = "Bringt 8 Klumpen verseuchte Erde zu Häuptling Orkan in Taunka'le.", progress = "Habt Ihr die Erde bei Euch, welche die Weise Aeire benötigt, um den Umhang fertig zu stellen?", completion = "<Häuptling Orkan nimmt die Klumpen Erde, die Ihr gesammelt habt, vorsichtig entgegen.>\n\nWir sollten die Dinger so schnell wie möglich zur Weisen Aeire bringen.\n\nDer Häuptling grunzt und gibt ein Murren von sich und tut so, als würde ihn der verdorbene Schmutz nicht stören.>\n\nWir können nie wissen, wann der Kommandant der Geißel seinen finalen Angriff auf das Dorf starten wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[11631] = { id = 11631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vision der Luft", description = "Hier, {name}, ich habe die Urluft auf Euch abgestimmt.\n\nÖffnet in Anwesenheit meines Totems der Luft Eure Seele und konzentriert Euch auf Scharfseher Grimmläufers Schicksal.\n\nDer Geist des Windes berührt alles - wenn wir Glück haben, wird man Euch eine Vision gestatten.", sourceObjective = "Vollzieht mithilfe von Impereans Urluft ein Ritual bei Fletschfangs Totem im Außenposten Bor'gorok, um Informationen über Scharfseher Grimmläufer zu beschaffen.\n\nSprecht anschließend mit Geistredner Fletschfang.", progress = "Bringt die Urluft wieder zu mir, wenn Ihr das Gefühl habt, genug gesehen zu haben.", completion = "Sie haben seinen Geist in Ketten gelegt. {name}, wir müssen seiner Qual ein Ende setzen!\n\nIhr müsst Euch in das Herz Magmuts begeben und einen Weg finden, ihn zu befreien!", sourceObjectiveStatus = "unverified-source-field" }
quests[11632] = { id = 11632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was der kalte Wind mit sich bringt...", description = "Ihr haltet das Knochenpanzerfragment von Ith'rix dem Ernter in Euren Händen und erkennt, dass dies erst der Anfang ist. Selbst jetzt spürt Ihr, dass der Sieg nur von kurzer Dauer sein wird. Der Lichkönig wird sicherlich noch Tausende Biester wie Ith'rix haben, die nur darauf warten, auf die Horde losgelassen zu werden.\n\nNehmt Eure Trophäe und präsentiert sie Hochfürst Saurfang in der Kriegshymnenfeste. Er sollte davon in Kenntnis gesetzt werden, dass Ihr einen mächtigen Agenten der Geißel besiegt habt.", sourceObjective = "Bringt Ith'rix' gehärteten Knochenpanzer zu Hochfürst Saurfang in der Kriegshymnenfeste.", progress = "Was habt Ihr denn da?", completion = "<Ein Grinsen zieht sich über Saurfangs Gesicht.>\n\nKommt mir bekannt vor... Mit der Macht von Kalimdor wurden in der Wüste von Silithus tausend Insekten wie dieses hier zertrampelt.\n\nDer Ort hier ist anders, die Umwelt anders, doch die Ergebnisse werden dieselben sein.\n\n<Saurfang inspiziert Euch.>\n\nIhr werdet die Horde in Nordend Stolz machen und ihr alle Ehre bereiten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11633] = { id = 11633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dabei sein ist alles", description = "Die Weise Aeire hat das Tuch fertig gestellt. Nehmt es mit und begebt Euch zur Tempelstadt En'kilah. Werft es Euch über, sobald Ihr Euch in der Stadt befindet, um Euch vor den meisten der dort hausenden Dienern der Geißel zu verbergen. Das wird unsere beste Möglichkeit sein, Informationen über die Befestigungen und Anführer unserer Feinde zu sammeln.\n\nKundschaftet die drei großen Säulen der Stadt aus, während Ihr den Umhang übergezogen habt. Das Tuch wird Euch von den meisten Dienern der Geißel beschützen, doch die Monstrositäten der En'kilah werden Euch finden, wenn Ihr zu nah an sie herankommt.", sourceObjective = "Häuptling Orkan in Taunka'le möchte, dass Ihr das magieerfüllte Tuch der Geißel in der Tempelstadt En'kilah überwerft und die Säule des Blutes, die Säule der Pein und die Säule der Fäulnis auskundschaftet.", completion = "<Häuptling Orkan hört Euch aufmerksam zu, als Ihr von Euren Beobachtungen berichtet.>\n\nDie Informationen, die Ihr gesammelt habt, werden uns bei der Planung unseres Angriffs auf die Tempelstadt helfen. Wir werden einen Weg finden müssen, die von Euch identifizierten Offiziere zu besiegen und Zugang zu dieser Nekropole zu erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11634] = { id = 11634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windreitermeister To'bor", description = "Ihr seid ganz schön hart, {name}. Ich denke, dass Eure Talente woanders besser aufgehoben wären - ich spreche von der Wurzel des ganzen verdammten Problems!\n\n<Razgor deutet in Richtung Westen.>\n\nDort befinden sich tausend Diener der Geißel, mindestens zwei schwebende Todesmaschinen und wer weiß was sonst noch.\n\nAber Ihr werdet es herausfinden und Euch darum kümmern... Das ist richtig, Ihr werdet der Armee der Geißel, die gerade dabei ist, unsere Tür einzutreten, die Hölle heiß machen.\n\nGeht zur Spitze der Kriegshymnenfeste und meldet Euch bei Windreitermeister To'bor. Er wird Euch erwarten.", sourceObjective = "Meldet Euch bei Windreitermeister To'bor in der Kriegshymnenfeste.", completion = "He, Mann! Hab dich erwartet.\n\n<To'bor deutet gen Westen.>\n\nWirf mal 'nen kurzen Blick da rüber. Auf der ander'n Seite der Tundra ist der Tod, Mann... Tod.", sourceObjectiveStatus = "unverified-source-field" }
quests[11635] = { id = 11635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scharfseher Grimmläufers Geist", description = "Ihr müsst nach Magmut im Osten.\n\nIhr müsst in die Tiefen der Höhlen hinabsteigen.\n\nIhr müsst mit dem Geist von Scharfseher Grimmläufer sprechen!", sourceObjective = "Sprecht mit dem Geist von Scharfseher Grimmläufer im Inneren von Magmut.", completion = "Ich danke Euch für die Atempause, {class}. Wenn wahre Freiheit für mich doch nur so einfach zu erringen wäre.", sourceObjectiveStatus = "unverified-source-field" }
quests[11636] = { id = 11636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritt auf dem magischen Teppich", description = "Danke, Maan. Ich sprech von Belagerungsmaschinen! An der Westküste bei Garroshs Landeplatz ham wir schwere Panzer stationiert. Wir werden Euch zu diesen Panzern bring'n und Ihr werdet einen davon benutz'n, um der Geißel zu zeig'n, was passiert, wenn die Horde Gerechtigkeit walt'n lässt!\n\nDer einzig schwierige Teil des Ganzen wird's sein, Euch dorthin zu bring'n. Kommt nich' in Frage, dass wir Euch auf einem unserer Windreiter dorthin schick'n. Zu riskant.\n\nSeht Ihr das Feenwesen da drüben? Den elfischen Blondschopf? Yanni heißt der, Maan. Er kann Euch sicher zur Küste bring'n. Sprecht mit Vernichter Grek'lor, sobald Ihr dort seid!", sourceObjective = "Sprecht mit Yanni in der Kriegshymnenfeste, um die sichere Reise zur Küste zu arrangieren. Sprecht mit Vernichter Grek'lor, sobald Ihr bei Garroshs Landeplatz angekommen seid.", completion = "DEN TOTEN KEINE GNADE!\n\nKeiner von denen hatte den Mumm, zurückzubleiben und unsere prächtigen Panzer zu verteidigen, nachdem Höllschrei die Küste für 'verdammt' erklärte. Zumeist ist es hier ruhig, da sich die Geißel gerade neu formiert, um schließlich die Kriegshymnenfeste anzugreifen. Manchmal begegnet mir ein vereinzelter Zombie oder Ghul, aber die machen's normalerweise nicht lange.\n\nNatürlich ist da dann auch der Nebel...\n\n<Grek'lor erschaudert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11637] = { id = 11637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaganishu", description = "Nachdem mein kleiner Trupp Grunzer getötet wurde, schleppte man mich hier runter und vollzog ein Ritual, an dessen Ende mein Tod stand. Derjenige, der dafür verantwortlich ist, heißt Kaganishu.\n\nIhr habt zwar seine Schamanengehilfen bezwungen, doch mein Geist ist noch immer an diesen Ort gebunden. Nachdem er mich erschlug, nahm er meinen Körper und erschuf daraus einen Fetisch, der mich jetzt hier gefangen hält. Mit seiner Hilfe lernt Kaganishu all das, was ich über Schamanismus weiß.\n\nIhr müsst ihm den Fetisch wegnehmen und ihn auf meinen Geist anwenden. Kaganishu befindet sich in den Höhlen hier in der Nähe.\n\nNur dann werde ich wirklich frei sein.", sourceObjective = "Findet Kaganishus Fetisch und wendet ihn auf die Überreste von Scharfseher Grimmläufer an.\n\nIhr werdet nach Magmut gehen und den Fetisch Scharfseher Grimmläufers Geist geben müssen.", progress = "Beeilt Euch, {class}, wendet den Fetisch auf mich an, bevor es zu spät ist.", completion = "Ich bin frei. Vielen Dank, {name}.\n\nUnd nun habe ich eine letzte Bitte an Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[11638] = { id = 11638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt meine Überreste zurück", description = "{name}, würdet Ihr, nun da mein Geist befreit wurde, mir die Ehre erweisen und meine Überreste zu Geisterflüsterin Fletschfang bringen? Sie liegen auf dem Boden zu meinen Füßen.\n\nIch spüre, dass die Geisterflüsterin sich noch immer im Außenposten Bor'gorok gen Westen befindet, dort wo ich sie zum letzten Mal sah.", sourceObjective = "Bringt Scharfseher Grimmläufers Überreste, die zu Füßen seines Geistes liegen, zur Geisterflüsterin Fletschfang im Außenposten Bor'gorok.", progress = "Ihr kehrt früher zurück, als ich erwartet habe. Was habt Ihr erfahren können?", completion = "Ich danke Euch dafür, dass Ihr seinen Geist aus Kaganishus Griff befreit habt und mit seinen Überresten zurückgekommen seid. Wir verfügen über wenig, mit dem wir Euch belohnen könnten, doch Ihr dürft nehmen, was auch immer Ihr zu Gesicht bekommt.\n\nUnd nun werde ich ihn zurück zu den Lebenden befördern - dort wo er hingehört.", sourceObjectiveStatus = "unverified-source-field" }
quests[11639] = { id = 11639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache an Magmut", description = "Der Oberanführer verbietet dem Schamanen, meine Wunden zu heilen. Er sagt, es sei eine gute Lektion für mich und gebe mir Zeit, um über mein Versagen nachzusinnen.\n\nDoch Ihr könntet mich und all jene, die in Magmut fielen, rächen!\n\nIch weiß, dass die Geisterflüsterin will, dass Ihr Euch dorthin begebt und den Weissager befreit.\n\nEs ist ganz in der Nähe im Osten. Geht, {class}... Geht und erschlagt die Magnatauren und ihre Schneebolddiener. Stellt die Ehre des Außenpostens wieder her!", sourceObjective = "Tötet 10 Schamanen der Magmut, 5 Futterwühler der Magmut, 3 Zermalmer der Magmut und 3 Gefährtinnen von Magmutregar. Kehrt anschließend zu Ortrosh im Außenposten Bor'gorok zurück.", completion = "Die Toten werden durch unsere Taten geehrt, {name}.\n\n\n\nVielleicht kann ich jetzt wieder zu dem Krieger werden, der ich einst war.", sourceObjectiveStatus = "unverified-source-field" }
quests[11640] = { id = 11640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worte der Macht", description = "In den Säulen, die Ihr beschrieben habt, hausen die Oberleutnants des Anführers der Geißel: die Hohepriester. Sie befehligen nicht nur die Truppen der Geißel, sondern besitzen auch den Schlüssel zur Nekropole über ihnen und damit auch zum Meister.\n\nEin endloser Strom von Dienern der Geißel wird uns überrennen, wenn wir nicht ihren Anführer finden und besiegen können. Ich kann meine Leute nicht schutzlos zurücklassen, egal wie sehr Durm auch den Kampf zum Feind tragen möchte. Es fällt also Euch zu, {name}, die Hohepriester zu töten und die Schriftrollen, die sie bei sich tragen, an Euch zu nehmen.", sourceObjective = "Bringt die Rolle von Hohepriester Naferset, die Rolle von Hohepriester Talet-Kha und die Rolle von Hohepriester Andorath zu Häuptling Orkan in Taunka'le.", progress = "Wir müssen in diese Nekropole hineinkommen, wenn wir durch die Reihen der Geißel brechen wollen und den Weg für die Dorfbewohner freimachen wollen.", completion = "<Häuptling Orkan liest den Text, der auf den Schriftrollen geschrieben steht.>\n\n'Shabtir bakh sokhen.'\n\nWorte der uralten, harten Sprache der Neruber und derjenigen, die darin begabt sind.\n\n'Der Diener unterwirft sich des Meisters Autorität.' Dies sind die Worte, die Euch den Eintritt in die Nekropole gewähren werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[11641] = { id = 11641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein mutiger Schlag", description = "Von Anfang an habe ich dazu geraten, dass Häuptling Orkan unsere mächtigen Krieger sammeln und unseren Feind in seiner Basis angreifen soll. Mein Ratschlag drang in taube Ohren und er hat bewiesen, dass er lieber Zeit verplempert, wie es die Weise Aeire vorgeschlagen hat.\n\nIch werde nicht länger warten. Wenn Häuptling Orkan zu feige ist, unsere Krieger in die Schlacht zu schicken, dann werdet vielleicht Ihr dazu bereit sein, ihm zu zeigen, dass ein Frontalangriff Erfolg haben kann. Erstürmt die Tempelstadt En'kilah und erschlagt alles, was sich Euch in den Weg stellt, {name}.", sourceObjective = "Erschlagt 15 Ghule der En'kilah und 5 Nekromanten der En'kilah und meldet Euch dann wieder bei Durm Eisbalg. Er befindet sich in Taunka'le.", completion = "Ihr habt Eure Furchtlosigkeit bewiesen und Euer Können im Kampf gezeigt. Ich glaube, dass Ihr einen guten Krieger der Taunka abgeben würdet. Ich wünschte nur, dass der Häuptling dasselbe Verständnis aufbringen könnte.\n\nAngesichts der Tatsache, dass wir verzweifelt versuchen das Dorf zu evakuieren, bevor es von der Geißel überrannt wird, können wir uns glücklich schätzen, Euch als Verbündeten an unserer Seite zu wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11642] = { id = 11642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Panzer reparieren sich nicht von selbst", description = "Wir müssen diese Panzer wieder zum Laufen bringen! Die werden sich nicht von selbst reparieren. Mobu wird sich darum kümmern. Sprecht mit ihm und seht nach, was er braucht. Vielleicht könnt Ihr ihn dazu bringen, endlich seinen Mund zu halten, bevor er mich endgültig zum Ausrasten bringt und ich ihn entzwei spalte!", sourceObjective = "Sprecht mit Mobu auf Garroshs Landeplatz.", completion = "Ihr seid der neue Panzerfahrer? Ich hab' nichts dagegen! Wir müssen diese Dinger nur wieder zum Laufen bringen. Ähm, ja, wenn Ihr Euch ohne Panzer auf die Ebene von Nasam wagt, seid Ihr so gut wie tot.", sourceObjectiveStatus = "unverified-source-field" }
quests[11643] = { id = 11643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mobus pneumatisches Panzertransjigamarick", description = "Die Schraubenschlüssel sind zu nichts zu gebrauchen, {class}. Ich brauche mein pneumatisches Panzertransjigamarick, um diese Dinger wieder zum Laufen zu bekommen! Unglücklicherweise hab ich es in meiner alten Bude auf der anderen Seite dieses Landeplatzes gelassen. Das ist die heruntergekommene Hütte neben den Ställen. Ihr werdet dorthin gehen und sie für mich holen müssen, weil ich in diesem Nebel ganz sicher nirgendwo hingehen werde.\n\nOh ja, {class}, nehmt Euch vor dem Nebel in Acht. Der Nebel ist es, der diese Küsten in Stücke riss.", sourceObjective = "Mobu an der Echoküste in der Boreanischen Tundra möchte, dass Ihr sein pneumatisches Panzertransjigamarick beschafft.", progress = "Habt Ihr das P.P.T. gefunden?", completion = "Gute Arbeit, {class}! Wo hab' ich nur diese Ersatzteile gelassen...", sourceObjectiveStatus = "unverified-source-field" }
quests[11644] = { id = 11644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superstarke Metallplatten!", description = "Ich brauche Metall, um diese Panzer zusammenzuflicken! Superstarke Metallplatten liegen überall auf Garroshs Landeplatz und auf dem Grund der Bucht verstreut.\n\nSeid nur vorsichtig, wenn Ihr dort draußen seid und nach Platten sucht. Der Nebel ist... ähm... AGGRESSIV! Der Nebel war es, der den Landeplatz und die angrenzende Tuskarrsiedlung zerstörte. Arme, kleine Tuskarr...", sourceObjective = "Mobu an der Echoküste in der Boreanischen Tundra möchte, dass Ihr 10 superstarke Metallplatten sammelt.", progress = "Vergesst nicht: Der Nebel ist böse!", completion = "Gute Arbeit, {class}! Wo hab' ich nur diese Ersatzteile gelassen...", sourceObjectiveStatus = "unverified-source-field" }
quests[11645] = { id = 11645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreckige, stinkende Schneebolde!", description = "Diese dreckigen, stinkenden Schneebolde... die haben alle meine Vorräte geklaut!\n\nWelche Schneebolde fragt Ihr? Sie sehen wie Kobolde aus, nur, dass sie den Magnatauren dienen, irgendwie sogar auf sie Acht geben. Ich weiß - seltsam!\n\nAber egal. Wollt Ihr mir aushelfen? Ich weiß, dass die kleinen Kriecher sich mit meinem ganzen Zeugs davongestohlen haben. Dumm von mir zu denken, dass sie an der Nordseite des Landeplatzes sicher wären.\n\nWieso tut Ihr mir nicht einen Gefallen und begebt Euch in Richtung Norden zu ihrem dummen Magnamut. Ich werde auch Gold dafür lockermachen, wenn Ihr mir all mein Zeug schnell zurückbringt!", sourceObjective = "Bringt 10 von Pfiffis Werkzeugen zu Pfiffi Wackelspross. Sie befindet sich bei der Landebahn Kurbelzisch.", progress = "Habt Ihr alle meine Vorräte dabei, {class}? Ich kann einfach NICHTS machen, wenn ich nicht all mein Zeug hab'!", completion = "Oh, {name}, Ihr seid einfach der Beste!\n\nHier, wie versprochen: Eure Bezahlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[11646] = { id = 11646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Boreanische Inquisition", description = "Hört genau zu, {name}, denn wir haben keine Zeit zu verlieren.\n\nEuer Gefangener wird hier in unserem Turm auf die Vernehmung vorbereitet. Eure Hilfe könnte vonnöten sein, falls wir uns begrenzter Zusammenarbeit gegenübersehen.\n\nMacht Euch auf den Weg dorthin, wo er festgehalten wird, und sagt Bibliothekar Normantis, dass ich Euch zu seiner Unterstützung geschickt habe.", sourceObjective = "Donathan hat Euch befohlen, Bibliothekar Normantis Eure Hilfe anzubieten. Er befindet sich im Magierturm auf dem Bernsteinflöz.", completion = "Es war weise von Donathan, Euch zu schicken, {class}.\n\nWie sich zeigt, habe ich gerade Verwendung für jemanden außerhalb der Kirin Tor.", sourceObjectiveStatus = "unverified-source-field" }
quests[11647] = { id = 11647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kessel neutralisieren", description = "Die Seuchenkesseln innerhalb der Tempelstadt En'kilah bereiten mir große Sorgen, {name}. Es steht fest, dass Häuptling Orkan Eurem Urteil und Wissen über unseren Feind traut. Würdet Ihr mir bei den Kesseln zur Hand gehen, wenn Ihr schon dabei seid, dem Häuptling bei der Umsetzung seiner Pläne in der Tempelstadt zu helfen?\n\nIch habe ein Totem vorbereitet, das den Inhalt der Kessel angreift und neutralisiert. Alles, was Ihr tun müsst, ist, die Kessel zu finden und das Totem bei jedem zu benutzen. Jede Waffe der Geißel, die wir zerstören, bringt uns dem Sieg einen Schritt näher.", sourceObjective = "Die Weise Aeire in Taunka'le möchte, dass Ihr mithilfe ihres Totems den Kessel im Osten, den Kessel in der Mitte und den Kessel im Westen der Tempelstadt En'kilah neutralisiert.", completion = "<Die Weise Aeire nimmt das Totem von Euch entgegen.>\n\nHat das Totem funktioniert? Es vorzubereiten hat uralte Magie beansprucht, die von den Weisen seit Generationen nicht mehr angewandt wurde. Von all dem überlieferten Wissen findet heute nur noch ein Bruchteil Anwendung.", sourceObjectiveStatus = "unverified-source-field" }
quests[11648] = { id = 11648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überredungskunst", description = "Wie praktisch, dass Ihr hier seid, {race}.\n\nIhr müsst verstehen, dass der Verhaltenskodex der Kirin Tor unser Ergreifen 'extremer' Mittel nicht duldet - selbst in Zeiten der Verzweiflung wie diesen.\n\nIhr jedoch als Außenstehender seid nicht an solche Einschränkungen gebunden und könntet jedes Mittel einsetzen, um an Informationen heranzukommen.\n\nTut, was Ihr tun müsst. Wir müssen umgehend in Erfahrung bringen, wo Lady Evanor gefangen gehalten wird!\n\nIch werde mich in der Zwischenzeit mit dem Ordnen dieser Regale beschäftigen. Oh ja, und hier, vielleicht nützt Euch dieses alte Ding...", sourceObjective = "Bibliothekar Normantis vom Bernsteinflöz möchte, dass Ihr den Neuralinjektor so lange auf den eingesperrten Beryllzauberer anwendet, bis er den Aufenthaltsort von Lady Evanor verrät.", progress = "Nun? Wisst Ihr, wo sich Lady Evanor aufhält?", completion = "Ausgezeichnet! Es war äußerst wichtig, dass wir diese Informationen erhalten.\n\nGut gemacht, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11649] = { id = 11649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Partikel der Wutentbrannten", description = "Da wir uns um ihre kleine Streiterei gekümmert haben, bleibt noch übrig, dass wir Euch und Eurer Geisterflüsterin helfen.\n\nWie Ihr seht, wurden meine Vasallen vom anhaltenden Krieg zwischen Feuer und Wasser erzürnt. Das wird sich so bald auch nicht ändern, doch für Euch wird es von Vorteil sein.\n\nUm Euch zu helfen, benötigen wir ihre Partikel. Dringt tiefer in die Ruinen ein und beschafft sie Euch von den Sturmwesen.", sourceObjective = "Beschafft 5 Sturmpartikel und bringt sie zu Imperean in den Ruinen von Eldra'nath.", progress = "Sobald Ihr die benötigten Partikel habt, werde ich sie mit einem Teil meiner Essenz verbinden. Das Resultat wird Euch das geben, was Ihr benötigt.", completion = "Ich bedauere den Verlust dieser Sturmwesen, doch ich halte mein Wort... selbst gegenüber einem Sterblichen wie Euch.\n\nNun lasst uns doch mal sehen, ob wir etwas Nützliches fertigen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11650] = { id = 11650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur noch ein paar Kleinigkeiten...", description = "Wie Ihr vielleicht gemerkt habt, haben wir den Landeplatz auf der südlichen Grenze eines Magnataurenbaus errichtet!\n\n<Pfiffi murmelt etwas Gemeines über Kurbelzisch.>\n\nDer Alte hat mir die Verantwortung übertragen, eine... ähhm... kreative Lösung für dieses Problem zu finden. Denn wenn wir nicht bald was gegen sie unternehmen, werden sie runterkommen und uns alle Gliedmaßen einzeln ausreißen!\n\nHier kommt Ihr also ins Spiel. Ich möchte, dass Ihr mir alles auf dieser Einkaufsliste besorgt. Bitte.", sourceObjective = "Findet Pfiffis Werkzeuge, einen überladenen Kondensatoren und eine Handvoll von Felsnars Kies. Bringt dies alles zu Pfiffi Wackelspross, die sich auf Kurbelzischs Landebahn aufhält.", progress = "Wieso fällt es mir schwer, Euch zu glauben, dass Ihr alle Gegenstände auf meiner Liste eingesammelt habt?", completion = "Nun gut, das ist schon besser! Das Einzige, was wir jetzt noch machen müssen, ist, all das Zeugs hier zusammenzubauen.\n\nJa, alles klar, als ob Ihr mir dabei helfen würdet.\n\nImmer mit der Ruhe, das wird nur 'ne Sekunde dauern, da ich ja jetzt meine Werkzeuge wieder habe!", sourceObjectiveStatus = "unverified-source-field" }
quests[11651] = { id = 11651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Danke vielmals...", description = "Vielen Dank für all Eure Hilfe, Kumpel. Ihr könnt Grek'lor sagen, dass die Panzer einsatzbereit sind. Hoffentlich könnt Ihr diesen Ort ein für alle Mal säubern!", sourceObjective = "Sprecht mit Vernichter Grek'lor an der Echoküste.", completion = "Aufgrund des gegenwärtigen Zustands unserer Transport- und Schiffswege, konnten wir keine einzige Belagerungsmaschine zur Kriegshymnenfeste schaffen. Diese Panzer sind alle, die von der ursprünglichen Expedition übrig geblieben sind. Nun, da sie einsatzbereit sind, werdet Ihr sie dazu benutzen, die Offensive in der Ebene von Nasam zurückzuschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11652] = { id = 11652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ebene von Nasam", description = "Springt in einen der Panzer und fahrt auf die südlich von hier gelegene Ebene von Nasam, sobald Ihr bereit seid.\n\nMacht vom Waffenarsenal des Panzers Gebrauch, um die Armee der Geißel auszuschalten. Solltet Ihr in Schwierigkeiten geraten, wird sie der \"Fleischklopfer\" in Stücke reißen und die Landminen werden ihnen den Todesstoß versetzen! Sollten Euch ein paar unserer Soldaten über den Weg laufen, dann schnappt sie Euch! Und noch etwas: Überall in dem Gebiet können Treibstofftanks gefunden werden.\n\nVersucht nah genug an das Gebäude in der Mitte heranzukommen und seht nach, was dort vor sich geht.\n\nGeht zu Höllschrei, falls Ihr das alles durchsteht!", sourceObjective = "Tötet mithilfe des Belagerungspanzers der Horde 100 Soldaten der Geißel und rettet 3 verletze Soldaten des Kriegshymnenklans auf der Ebene von Nasam. Außerdem müsst Ihr herausfinden, wer der Anführer des Angriffs der Geißel ist.\n\nMeldet Euch bei Garrosh Höllschrei in der Kriegshymnenfeste, solltet Ihr Erfolg haben.", completion = "Kel'Thuzad? Es ist also wahr - Naxxramas kehrt wieder zurück...\n\nVielleicht habe ich Euch unterschätzt, {name}. Ihr habt der Horde einen großen Dienst erwiesen. Der Kriegshäuptling wäre stolz auf Euch!\n\n\n\nWenn Kel'Thuzad diese Diener der Geißel kontrolliert, ist nicht abzusehen, was der Lichkönig sonst noch für uns auf Lager hat... Ich brauche Zeit, um mir diese neue Information durch den Kopf gehen zu lassen, {name}. Ihr könnt wegtreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11653] = { id = 11653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ha! ... Jetzt seid Ihr nicht mehr so groß!", description = "Das wird's ihr zeigen, <Chef/Chefin>! So, das hier müsst Ihr also für mich machen...\n\nNehmt meinen Blaster und begebt Euch in Richtung Norden nach Magmut. Wenn wir irgendeine Chance gegen diese Monster haben wollen, dann müssen wir sie einen Kopf kürzer machen... um es mal so zu sagen.\n\nUm abzuschätzen, wie effektiv das ist, müsst Ihr für mich die Magnatauren töten, während die Effekte des Blasters noch immer auf sie wirken. Die Zermalmer oder Gefährtinnen werden genügen, den Nachwuchs könnt Ihr ignorieren... die sind zu klein, um sich darüber Sorgen machen zu müssen.", sourceObjective = "Testet Pfiffis ultrafortschrittlichen prototypischen Verkürzungsblaster an 5 Zermalmern der Magmut oder Gefährtinnen von Magmutregar aus. Kehrt wieder zu Ihr zurück, sobald Ihr das erledigt habt. Sie befindet sich auf der Landebahn Kurbelzisch.", progress = "Seid Ihr Euch sicher, dass Ihr den Blaster an genug dieser monströsen Biester ausgetestet habt?", completion = "Was meint Ihr damit: Es hat nicht funktioniert?!\n\nAber... aber...\n\n<Pfiffi fängt an zu weinen.>\n\nOkay, damit können wir fertig werden. Ich bin ein großes Mädchen. Zeit, über den Tellerrand hinaus zu sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11654] = { id = 11654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Säule des Blutes", description = "Als Ihr die Phiole mit Blut, die Ihr gefunden habt, untersucht, fällt Euch auf, dass der Inhalt noch immer warm ist. Das Opfer muss gerade eben erst Blut gelassen haben und noch immer am Leben sein.\n\nWelchen Nutzen hat die Geißel für Blut? Sie waren in der Vergangenheit nie an lebenden Gefangenen interessiert. Wenn Ihr den Ursprung des Blutes finden könnt, dann könnt Ihr vielleicht herausfinden, was die Geißel vorhat.", sourceObjective = "Sucht in der Säule des Blutes nach weiteren Informationen über die Phiole mit frischem Blut.", progress = "Wie... wie habt Ihr mich gefunden?", completion = "<Der Schneefährtenleser der Taunka wirkt geschwächt und kann Euch gerade noch antworten.>\n\nIch habe nicht... lange. Vielleicht... Vielleicht könnt Ihr sie aufhalten... bevor...", sourceObjectiveStatus = "unverified-source-field" }
quests[11655] = { id = 11655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Nebel hinein", description = "Auf der anderen Seite des Nebels gen Norden werdet Ihr Garroshs Landebahn vorfinden. Im Süden liegen die Ruinen meiner alten Heimat Pal'ea. Beide Orte wurden von den Kvaldir, einer uralten Macht, ausgeplündert.\n\nDiese Furcht erregenden Barbaren erschlugen gnadenlos alle meine Brüder und Schwestern und trieben Eure Leute ins Landesinnere.\n\nAlles, was von den Tuskarr aus Pal'ea übrig bleibt, sind die persönlichen Hinterlassenschaften, Relikte sozusagen, die von den Kvaldir mitgenommen wurden. Wir sind zwar kein rachsüchtiges Volk, doch Gerechtigkeit muss walten. Die Relikte der Tuskarr müssen zu mir zurückgebracht werden. Begebt Euch in den Nebel und findet sie...", sourceObjective = "Waltor von Pal'ea an der Echoküste in der Boreanischen Tundra möchte, dass Ihr Kvaldir tötet und 8 Relikte der Tuskarr beschafft.", progress = "Mit Blut und Ruhm müsst Ihr dienen... Bringt die Relikte der Tuskarr wieder zurück.", completion = "<Waltor wird von Trauer ergriffen.>\n\nSchutt und Asche... das ist alles, was sie zurückgelassen haben. Ihnen muss eine Lektion erteilt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[11656] = { id = 11656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setzt ein Zeichen und verbrennt sie", description = "Die Magie der Tuskarr ist dem Schamanismus, wie er von Eurem Volke genannt wird, ähnlich. Während wir den Elementen im Vergleich zu Euch auf verschiedene Art und Weise dienen, ist die Macht, die wir beschwören können, eindrucksvoll.\n\n<Waltor hantiert mit einem fackelähnlichen Stab vor Euch herum.>\n\nIch möchte, dass Ihr mit dieser Tuskarrfackel in den Nebel zurückkehrt und einen Schlag gegen die Schiffe der Kvaldir führt. Ihr werdet drei ihrer Schiffe gen Norden, bei Garroshs Landeplatz auf der anderen Seite des Nebels, angedockt vorfinden, und ein weiteres in Richtung Süden, vor der Küste Pal'eas. Steckt ihre Schiffe in Brand und setzt damit ein Zeichen! Damit es ein jeder sehen kann!", sourceObjective = "Waltor von Pal'ea an der Echoküste in der Boreanischen Tundra möchte, dass Ihr die Tuskarrfackel benutzt und die Schiffe der Kvaldir bei Pal'ea und Garroshs Landeplatz verbrennt. Ihr müsst die folgenden Schiffe verbrennen: Die Schlangenschlund, die Kur Drakkar, die Bors Hammer und die Bors Amboss.", completion = "Den Kvaldir zu zeigen, dass wir ihnen Widerstand leisten, ist vielleicht das, was wir brauchen, um mein Volk in den anderen Lagern zu retten. Vielleicht werden die Kvaldir ihr Handeln überdenken, wenn sie glauben, dass es Vergeltung nach sich ziehen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[11657] = { id = 11657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fackeln fangen", description = "Da Ihr ja nun eine Fackel werfen könnt, lasst uns doch einmal sehen, ob Ihr auch eine fangen könnt!\n\nNehmt diesen Stapel unangezündete Fackeln, geht zum Freudenfeuer und werft eine davon hoch in die Luft! Fangt sie wieder auf, bevor sie auf den Boden fällt... und werft sie wieder in die Höhe! Fangt vier nacheinander und kommt wieder zu mir zurück.\n\nSeid vorsichtig! Die Fackeln sind gefährlich, wenn sie auf dem Boden aufkommen! Und fangt sie alle auf! Wenn eine davon auf den Boden fällt, müsst Ihr zurück zum Freudenfeuer und von vorn anfangen. Viel Glück.", sourceObjective = "Fangt nacheinander 4 Fackeln und sprecht anschließend mit dem Feuerschluckmeister.", progress = "Fackeln zu fangen macht jede Menge Spaß, meint Ihr nicht? Seid jedoch vorsichtig! Ihr wollt bestimmt nicht angesengt werden!", completion = "Habt Ihr Euch verbrannt? Falls ja, dann werdet Ihr es Euch in Zukunft zweimal überlegen, bevor Ihr mit Feuer herumspielt...\n\nScherz! Gut gemacht! Es ist nun offiziell: Ihr seid ein Feuerjongleur des Freudenfeuers. Nun geht und amüsiert Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[11658] = { id = 11658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plan B", description = "Okay, keine Panik! Der Blaster hat vielleicht nicht funktioniert, aber uns stehen noch immer Möglichkeiten offen.\n\n<Pfiffi schnippt mit den Fingern.>\n\nWir werden die Aufmerksamkeit von der Landebahn weglenken! Um das zu bewerkstelligen, brauchen wir zuerst ein paar Dinge.\n\n<Wackelspross mustert Euch von Kopf bis Fuß.>\n\nStahlkiefers Karawane gleich im Westen hat dummerweise eine Abkürzung durch einen Taunkafriedhof genommen und wurde von deren wiederauferstandenen Geistern zerstört.\n\nBegebt Euch dorthin und nehmt den toten Orcs ein paar Gewänder ab. Nehmt auch eines ihrer Banner mit!", sourceObjective = "Sammelt 10 Kriegshymnenausrüstungen und ein Kriegshymnenbanner. Bringt sie zurück zu Pfiffi Wackelspross an der Landebahn Kurbelzisch.", progress = "Wir werden viele ihrer Gewänder brauchen, wenn das hier funktionieren soll... Wir müssen einfach nur etwas finden, das Euch passt!\n\nUnd dann werd' ich einfach mal einen Hauch meiner genialen Ingenieursfertigkeit hinzufügen und puff ist Euer Aussehen wie für die Rolle, die Ihr spielen müsst, geschaffen.", completion = "Fein, aber diese Kleider stinken!\n\nMich persönlich würdet Ihr nie und nimmer in solchen Fetzen rumrennen sehen. Aber wir werden aus all den Dingern eines heraussuchen müssen, dass zu Eurer... Figur passt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11659] = { id = 11659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerschmettert die Kugeln!", description = "Sie lassen... die Gefangenen ausbluten... geben das Blut... in diese Kugeln.\n\n<Grumm schließt kurz die Augen und lehnt seinen Kopf zurück.>\n\nDas Blut... hoch zur Nekropole gebracht... um Blutprinzen satt zu machen...\n\n<Grumm ringt nach Luft.>\n\nVer-Versprecht mir... dass Ihr... Blutkugeln... zerstört... Nachricht an... Junek.\n\n<Der Schneefährtenleser fällt in Ohnmacht.>", sourceObjective = "Zerstört 5 Blutkugeln und meldet Euch anschließend bei Schneefährtenleser Junek in Taunka'le.", completion = "Ich hatte befürchtet, dass sie Grumm gefangen genommen haben, doch ich hätte niemals gedacht, dass sie ihm solch schreckliche Dinge antun würden. Ich habe noch nie miterlebt, dass ein Krieger eine verlorene Schlacht mit der Geißel überlebt.\n\nIch danke Euch dafür, mir berichtet zu haben, welch Schicksal ihn ereilte, {name}. Er war ein mächtiger Krieger und wir werden ihn als solchen in Erinnerung behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11660] = { id = 11660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Horn des uralten Seemanns", description = "Ein Leutnant der Kvaldir namens Orabus führte den Überfall auf mein Volk bei Pal'ea an. Er beaufsichtigte die Zerstörung beider Dörfer und verschwand anschließend im Nebel.\n\nIn diesen ersten Tagen ging das Wort um, dass ein Horn existiere, das Orabus den Nebelwirkern der Kvaldir zum Geschenk machte. Dieses Horn kann dazu benutzt werden, ihn, falls nötig, zu beschwören.\n\nWir müssen dieses Horn den Nebelwirkern der Kvaldir wegnehmen und Orabus heraufbeschwören. Wenn er zerstört ist, könnten sich die Barbaren vielleicht zurückziehen.\n\nSucht nach den Nebelwirkern im südlich gelegenen Pal'ea.", sourceObjective = "Waltor von Pal'ea an der Echoküste in der Boreanischen Tundra möchte, dass Ihr ihm das Horn des uralten Seemanns bringt.", progress = "Findet das Horn des uralten Seemanns!", completion = "Ihr müsst mithilfe des Horns des uralten Seemanns Orabus anrufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11661] = { id = 11661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orabus der Steuermann", description = "Nehmt das Horn an Euch und reist gen Westen zur Landebrücke des Kriegshymnenklans. Geht zum Ende der Landebrücke, presst das Horn an Eure Lippen und stoßt hinein. Das Geräusch sollte Orabus wecken.\n\nErschlagt das grauenhafte Ungetüm und kehrt zu mir zurück!", sourceObjective = "Waltor von Pal'ea an der Echoküste in der Boreanischen Tundra möchte, dass Ihr mithilfe des Horns des uralten Seemanns Orabus den Steuermann beschwört. Erschlagt Orabus den Steuermann, sobald er beschworen ist.", completion = "Es scheint, als hätte der Verlust ihres Leutnants sie nur wachgerüttelt. Sie sind wütender und aggressiver als je zuvor!\n\n<Walter seufzt.>\n\nIhr habt getan, was in Eurer Macht stand, {class}. Das Allermindeste, was Ihr verdient habt, ist eine Entschädigung dafür, dass Ihr sie dezimiert habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11662] = { id = 11662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht nach Karuk!", description = "Ein weiterer Überlebender von Pal'ea mit Namen Karuk hat sich auf den Weg zur Hauptbasis der Kvaldir in der Boreanischen Tundra gemacht - weit südlich von hier, dort, wo der Schnee einst reichlich war. Karuk versteckt sich irgendwo auf den Klippen, die am Strand der Peitschennarbe emporragen.\n\nSucht nach Karuk und lasst ihn wissen, was Ihr hier an der Echoküste für mein Volk geleistet habt.\n\nDer sicherste Weg zu Karuk führt durch Eure Festung. Von der Kriegshymnenfeste aus folgt Ihr der Straße in Richtung Süden bis zum Strand der Peitschennarbe.", sourceObjective = "Sucht Karuk am Strand der Peitschennarbe auf.", completion = "Es war klug von Waltor, Euch zu mir zu schicken, {race}. Die Götter schenken denjenigen ein Lächeln, die Gerechtigkeit walten lassen. Ihr werdet derjenige sein, durch welchen die Boshaften ihre gerechte Strafe erhalten werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[11663] = { id = 11663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheime Nachrichten teilen", description = "Ich danke Euch, {class}! Die Informationen, die Ihr herausbekommen habt, sind von entscheidender Bedeutung für die Kirin Tor.\n\nKehrt umgehend zu Donathan zurück, während wir uns Gedanken darüber machen, wie wir Lady Evanor nun befreien können.", sourceObjective = "Normantis möchte, dass Ihr Euch bei Bibliothekar Donathan auf dem Bernsteinflöz meldet.", completion = "Vergebt mir, {name}. Ich weiß, dass das unangenehme Arbeit war.\n\nWäre unsere Lage hier nicht so verzweifelt, hätte ich Euch nie darum gebeten, uns auf solch einer Art und Weise beizustehen.\n\nSo... Was habt Ihr entdeckt?", sourceObjectiveStatus = "unverified-source-field" }
quests[11664] = { id = 11664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus dem Nebel", description = "Ich kann die Kreaturen des Nebels draußen hören. Ihre Schreie treiben mich in den Wahnsinn, doch eine Flucht will ich nicht wagen. Und wo würde ich überhaupt hingehen? Wie lange würde es dauern, bis sie mich einholen und wie die anderen hinrichten?\n\nWie weit, so frage ich mich, ist der Nebel eigentlich schon gekrochen, <Fremder/Fremde>? Hat er schon den gesamten Kontinent erfasst?\n\nWäret Ihr willens, mir dabei zu helfen, dem Nebel zu entfliehen? Ich denke, dass ich uns zurück zu meinem Vater führen kann. Ich spüre seinen Lebensgeist noch immer. Er befindet sich in der Nähe.", sourceObjective = "Begleitet Muhtoo die Jüngere und helft ihr, aus dem Nebel herauszukommen. Sprecht mit dem Ältesten Muhtoo, solltet Ihr Muhtoo die Jüngere in Sicherheit gebracht haben.", completion = "Die Winde flüstern es, {name}. Euer Name ist den Elementen bekannt. Ihr habt Muhtoo an diesem heutigen Tage einen großen Dienst erwiesen und sollt dafür belohnt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[11665] = { id = 11665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krokilisken in der Stadt", description = "Hallo, <Junge/Mädchen>. Ich bin froh, dass Ihr vorbeigeschaut habt, um mit einem alten Mann zu sprechen - zuhause gibt es Schwierigkeiten.\n\nEin fliegender Händler hat neulich eine Ladung Krokiliskenbabys an ein paar leichtgläubige Kinder verkauft. Krokilisken sind wilde Bestien. Viele sind entkommen und halten sich jetzt in den Wasserwegen der Stadt verborgen.\n\nNehmt Eure stärkste Angelrute, werft sie in Sturmwind oder Orgrimmar aus und bringt einen der kleinen Teufel zurück zu mir. Ich kann es kaum erwarten, einen zu sehen.", sourceObjective = "Bringt dem alten Barlo ein Krokiliskenbaby. Ihr könnt ihn beim Angeln am Silmyrsee nordöstlich von Shattrath finden.", progress = "Schon Kroks in den Abwasserkanälen gefangen?", completion = "Was für eine miese kleine Kreatur! Ich bin mir sicher, dass der Rokk irgendwas Leckeres aus ihr machen wird.\n\nIch mach natürlich nur Spaß.\n\n<Der alte Barlo zwinkert neckisch.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11666] = { id = 11666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Köderbanditen", description = "Ihr wisst wahrscheinlich alles über den goldenen Stachelflosser - in den Flüssen von Terokkar kommen sie recht häufig vor, außerdem sind sie eine Delikatesse für Priester. Es gibt jedoch einen, von dem Ihr noch nicht gehört habt: den schwarzen Stachelflosser.\n\nDer Fisch ist berüchtigt für seine Gerissenheit und dafür, dass er schwierig einzufangen ist. Ihr müsst Eure Angelschnur in letzter Sekunde einziehen, denn sie knabbern am Köder, bevor sie sich ihn schnappen.\n\nWerft Eure Angelrute in den Gewässern von Terokkar aus und bringt mir einen schwarzen Stachelflosser. In Seen braucht Ihr gar nicht erst zu suchen - der Flitzer kommt nur in Fließgewässern vor.", sourceObjective = "Bringt dem alten Barlo einen schwarzen Stachelflosser. Ihr könnt ihn beim Angeln am Silmyrsee nordöstlich von Shattrath finden.", progress = "Wie fischt sich's denn heute, mein Junge?", completion = "Nun sieh mal einer an... Ihr habt einen Großen gefangen! Dieser alte Mann wird heute Abend gut essen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11667] = { id = 11667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Eine, der entkam", description = "Feigenschimmers Matschflosser ist ein erstaunlich schneller Gründler, den man in den Gewässern von Nagrand anfindet. Sie wachsen ihr ganzes Leben lang und sind als Kämpfer sehr bekannt.\n\nVor Jahren fing ich den größten Matschflosser der Welt, da bin ich mir sicher... Doch dann brachte er meine Leine zum Reißen und kam davon.\n\nEinem Angler Eures Kalibers muss man nicht sagen, was zu tun ist - Euer Schicksal erwartet Euch an den Seen von Nagrand.", sourceObjective = "Fangt den größten Matschflosser der Welt und bringt ihn zum alten Barlo. Ihr könnt ihn beim Angeln am Silmyrsee nordöstlich von Shattrath finden.", progress = "Sagt mir, dass Ihr ihn gefangen habt. Bitte sagt mir, dass Ihr den Mistkarpfen gefangen habt.", completion = "Da ist er! Diese Narbe würde ich immer wiedererkennen.\n\nAber um ganz ehrlich zu sein, habe ich ihn mir... größer vorgestellt. Tja - denke, dass ich ihn freilassen und es an einem anderen Tag noch einmal versuchen werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[11668] = { id = 11668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnelenfangen ist nicht einfach", description = "In den Seen der Zangarmarschen gibt es viele große Fische. Habt Ihr Euch jemals darüber Gedanken gemacht, was sie fressen?\n\nGarnelen - riesige Süßwassergarnelen. Der Rokk hat mir erzählt, dass man unendlich viele Garnelengerichte zubereiten kann.\n\nGarnelen sind jedoch zu klein, als dass man sie mit einer Angelschnur fangen könnte. Hier also der Trick: Schneidet eine aufgedunsene Stachelkiemenforelle auf und Ihr werdet, wenn Ihr Glück habt, die eine oder andere Garnele darin finden.", sourceObjective = "Bringt dem alten Barlo 10 riesige Süßwassergarnelen. Ihr könnt ihn beim Angeln am Silmyrsee nordöstlich von Shattrath finden.", progress = "Was haben wir denn heute gefangen, mein Junge?", completion = "Ihr könnt mit Haken und Messer gut umgehen. Reicht mir die süßen Leckerbissen und ich werde Euch davon kosten lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11669] = { id = 11669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsblutfilet", description = "Dieser alte Mann wird bald jagen gehen. Ich werde mir vor Azsharas Küste einen Mammuthai fangen.\n\nDie Sache ist nur, dass ich ein Toxin benötige, das auf einer Speerspitze haften bleibt, wenn man sich unter Wasser befindet. Um so etwas herzustellen, benötige ich die Drüsen eines giftigen Fischs: dem Teufelsblutschnapper.\n\nSolch ein abscheulicher Fisch gedeiht nur in den Gewässern der Höllenfeuerhalbinsel und des Schattenmondtals. Bringt mir das Mordsding und Ihr macht aus mir einen glücklichen alten Mann.", sourceObjective = "Bringt dem alten Barlo einen monströsen Teufelsblutschnapper. Ihr könnt Barlo beim Angeln am Silmyrsee nordöstlich von Shattrath finden.", progress = "Der Teufelsblut ist ein Wunder der Evolution. Er kann in allen Gewässern und sogar Lava überleben. Fischer sind seine einzigen natürlichen Feinde.\n\nGlück beim Beutefang gehabt?", completion = "Das ist der größte und hässlichste Fisch, den ich je gesehen habe. Ich kann mir gar nicht vorstellen, was Ihr als Köder benutzt habt.\n\nLegt das Biest einfach auf den Boden und ich werde mich darum kümmern, sobald ich mir sicher sein kann, dass es tot ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[11670] = { id = 11670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es waren die Orcs, ganz ehrlich!", description = "Ich habe aus all den Gewändern, die Ihr... ähm... gefunden habt, eine Verkleidung gefertigt, mit der Ihr wie ein Orc des Kriegshymnenklans aussehen werdet. Ich hatte die geniale Idee, sie mit ein paar alten Sachen zu kombinieren, die noch von den letzten Schlotternächten herumlagen, also sollte sie idiotensicher sein!\n\nHier, in diesem Sack befindet sich die Verkleidung und das Banner, das Ihr gefunden habt. Begebt Euch ins Innere von Magmut und erschlagt Magmutregar, den Häuptling der Magnatauren.\n\nWenn Ihr sie davon überzeugen wollt, dass sie ihre Aufmerksamkeit den Orcs des Kriegshymnenklans schenken sollen, werdet Ihr das Banner aufstellen müssen, solange Ihr verkleidet seid.", sourceObjective = "Spießt Magmutregars Leiche mit dem Kriegshymnenbanner auf, während Ihr als Orc des Kriegshymnenklans verkleidet seid. Kehrt anschließend zu Pfiffi Wackelspross zurück und bringt die Verkleidung mit. Sie befindet sich auf der Landebahn Kurbelzisch.", progress = "Es ist also vorbei? Ihr habt die Drecksarbeit gemacht und sie den Orcs vom Außenposten Bor'gorok in die Schuhe geschoben.", completion = "Du lieber Himmel, Ihr habt es getan!\n\nNun gut, diese lästigen Magnatauren und ihre Schneeboldlakaien sollten ihre Aufmerksamkeit auf die Horde richten.\n\nWie kann ich mich dafür jemals bei Euch erkenntlich zeigen, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[11671] = { id = 11671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wettlauf gegen die Zeit", description = "Es stimmt also: Sie haben sie.\n\nKeine Frage, was getan werden muss, {race}. Wir WERDEN sie befreien.\n\nIch muss hier bleiben und bei den Rettungsvorbereitungen helfen. Also wende ich mich noch einmal an Euch; dieses Mal mit der Bitte, den Gefängnisschlüssel zu finden. Alles, was wir über diese Salrand wissen, ist, dass sie nicht verletzt werden kann, solange ihr Schild noch intakt ist.\n\nWir haben einen speziellen Sprengsatz so präpariert, dass er sie ihres Schutzes berauben wird, damit Ihr Eure Pflicht tun könnt. Kehrt zu mir zurück, wenn Ihr den Schlüssel habt.\n\nBeeilt Euch, {name}. Lady Evanor erleidet Qualen!", sourceObjective = "Donathan vom Bernsteinflöz hat Euch damit beauftragt, mithilfe des Beryllschilddetonators den Schild auf der Beryllspitze zu zerstören. Danach sollt Ihr Salrand besiegen und ihr den Schlüssel abnehmen, den sie bei sich trägt.", progress = "Habt Ihr Salrands Schlüssel bei Euch?", completion = "Zerbrochen?\n\nLasst mich einmal sehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[11672] = { id = 11672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eingezogen", description = "Ihr seid zur Einberufung gekommen, richtig? Normalerweise müsstet Ihr genauso wie alle anderen Rekruten in einer Reihe stehen. Normalerweise hättet Ihr Pech, weil das Rekrutierungsregister abhandengekommen ist und ich niemanden aufnehmen kann, bis die neuen Bücher ankommen.\n\nDoch glücklicherweise, {name}, habe ich von Euch und Euren Taten in der Scherbenwelt gehört. Um ehrlich zu sein, seid Ihr den anderen Trotteln bei Weitem überlegen. In Reih und Glied stehen ist nichts für Euch.\n\nGeht zur Kaserne und sprecht mit General Arlos. Er wird mehr als froh darüber sein, jemanden Eures Kalibers zu treffen.", sourceObjective = "Trefft Euch mit General Arlos im Inneren der Kaserne in der Valianzfeste.", completion = "Wir haben Eure Ankunft erwartet, {name}. Willkommen in Nordend.", sourceObjectiveStatus = "unverified-source-field" }
quests[11673] = { id = 11673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holt mich hier raus!", description = "Ich habe gewusst, dass sie früher oder später jemanden schicken würden... später natürlich, wie sich zeigt.\n\nIch bin hierhergekommen, um mit den Schneebolden zu verhandeln, doch ihr wichtigster Schamane Kaganishu hat sich stattdessen dazu entschlossen, dass ich wohl besser als Leckerbissen für Magmutregar geeignet wäre.\n\nWartet... Wie bitte?! Sie haben Euch gar nicht geschickt?!\n\nHABEN SIE MICH ETWA VERGESSEN?!\n\nOkay, Ihr seid jetzt hier - das ist das einzig Wichtige.\n\nSobald Ihr diese Kette zerbrochen habt, werden wir uns auf den Weg zurück zur Landebahn machen. Dann könnt Ihr Kurbelzisch mitteilen, dass ich heil zurück bin.\n\nDas heißt, falls er sich überhaupt an mich erinnert.", sourceObjective = "Bringt Bonker Wechselvolt in Sicherheit und meldet Euch bei Kurbelzisch Vollgas auf der Landebahn Kurbelzisch.", completion = "Hä? Was?\n\nBonker wer?\n\nIch hab' keine Ahnung, von wem Ihr da sprecht, aber ich nehm' Euch beim Wort. Wenn Ihr ihn oder sie aus Magmuts Grube befreit habt, dann nehme ich mal an, Ihr habt Euch eine Belohnung verdient.\n\nLasst mich einmal nachsehen, was hier so herumliegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11674] = { id = 11674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Weise Hochmesa wird vermisst", description = "Viele neue Rätsel erzählt man sich nun landauf, landab. Eine unserer Weisen, Hochmesa, ist törichterweise mit einem Fernläufer gen Norden gegangen, um etwas Merkwürdiges bei den Höhlen des Todes zu untersuchen.\n\nWas sind das für Höhlen, fragt Ihr? Sie sind ein Heiligtum der Magnatauren, wo diese sich im Alter hinbegeben, um zu sterben. Vor ein paar Tagen sah sie in deren Nähe etwas vom Himmel fallen.\n\nWenn Ihr ein Freund der Taunka seid, so möchte ich Euch bitten, sie zu finden und ihr zu helfen. Sie ist nicht so dickköpfig, dass sie Eure Hilfe ablehnen würde.", sourceObjective = "Findet die Weise Hochmesa in der Nähe der Höhlen des Todes.", completion = "Die Großmutter hat Euch geschickt? Sie muss von mir enttäuscht sein.\n\nDoch als ich das große Objekt vom Himmel fallen sah, konnte ich nicht auf eine ganze Gruppe Fernläufer und Schneefährtenleser als Begleitung warten. Wissen wartet auf niemanden.", sourceObjectiveStatus = "unverified-source-field" }
quests[11675] = { id = 11675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein würdiges Ende", description = "Die Magnatauren bei den Höhlen des Todes haben sich mit einer Seuche infiziert. Wir müssen die Ursache finden, doch zuerst müssen wir ihrem Leiden ein Ende setzen.\n\n{race}, Ihr müsst in Richtung Norden die Hänge vor uns hinaufgehen und so viele der armen Kreaturen erschlagen wie nur möglich.", sourceObjective = "Erschlagt 10 verseuchte Magnatauren und kehrt anschließend zur Weisen Hochmesa gleich südlich der Höhlen des Todes zurück.", completion = "Was können wir sonst machen, außer sie von ihrem Leiden zu befreien? Auf jeden Fall kamen sie hierher, um zu sterben, also trauert nicht um sie. Zumindest habt Ihr sie in Würde sterben lassen.\n\nNun müssen wir der Ursache der Seuche ein Ende bereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11676] = { id = 11676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnadenvolle Freiheit", description = "Die Soldaten, die sie verschont haben, werden in Käfigen festgehalten, die überall auf diesem Ackerland verstreut herumstehen. Dank einiger Meisterstreiche in Sachen Diebstahl konnten wir zwar an ein paar Schlüssel gelangen, doch wir kommen einfach nicht an die Gefangenen heran, ohne uns Angriffen auszusetzen.\n\nWir benötigen Euer \"Geschick\", um diese Schlüssel zu sichern und die Gefangenen zu befreien. Schlagt den Nekrolords und Monstrositäten die Schädel ein und nehmt ihnen die Schlüssel ab. Befreit anschließend die Gefangenen mit diesen Schlüsseln.", sourceObjective = "Schattenpirscher Canarius auf den Höfen des Kriegshymnenklans möchte, dass Ihr 5 Gefangene der Geißel befreit.", completion = "Jeder befreite Gefangene ist eine untote Monstrosität weniger, um die wir uns kümmern müssen, {name}. Ihr habt der Horde einen großen Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11677] = { id = 11677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltet die Seuche auf", description = "Ich bin davon überzeugt, dass die Seuche von etwas ausgeht, das sich in den Höhlen dort oben befindet.\n\n{class}, nehmt diese Samen. Normalerweise verwende ich sie zum Schutz gegen die Geißel, doch vielleicht kann man mit ihnen auch die Höhle von all jenen Übeln befreien, die dort vor sich gehen.\n\nFindet den Quell dieser Seuche und werft sie dort hinein.", sourceObjective = "Die Weise Hochmesa gleich südlich der Höhlen des Todes möchte, dass Ihr Hochmesas reinigende Samen auf den Seuchenkessel in den Höhlen des Todes anwendet, um ihn zu neutralisieren.", completion = "<Die Weise lässt ihren Kopf hängen und seufzt vor Erleichterung.>\n\nDas ist ein guter Anfang. Wenn es doch nur unser einziges Problem wäre.", sourceObjectiveStatus = "unverified-source-field" }
quests[11678] = { id = 11678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet Borstenhorn", description = "Borstenhorn hätte schon längst zurückkommen sollen.\n\nDer andere Grund, wieso wir hierhergekommen sind, war die Untersuchung des Gebäudes der Geißel im Westen, das vom Himmel gefallen ist. Er ist impulsiv und hat sich höchstwahrscheinlich in Schwierigkeiten gebracht.\n\n{name}, geht dorthin und findet ihn, bitte.", sourceObjective = "Sucht in Talramas nach Fernläufer Borstenhorn.", completion = "Ich bin... nicht... lange für diese... Welt, kleiner {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11679] = { id = 11679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Schlüssel neu schmieden", description = "Verspätungen, Verspätungen... genau das, was wir uns gerade nicht leisten können!\n\nSo sehr ich es hasse, Lord Surristrasz zu stören, er ist die einzige Hoffnung, unsere geliebte Evanor zu retten.\n\nBringt die Schlüsselfragmente zu ihm und hofft, dass er guter Laune ist.\n\nBeeilt Euch, {class}, unsere Angriffstruppe wartet.", sourceObjective = "Donathan möchte, dass Ihr mit Surristrasz auf dem Bernsteinflöz sprecht.", progress = "Du wagst dich in meine Nähe, Sterblicher?\n\nBete und hoffe um deiner ungeborenen Kinder Willen, dass dein Anliegen die Mühe wert ist.", completion = "Die frivolen Spiele, die du hier treibst, führen zu nichts...\n\nDu und deine Verbündeten in Dalaran tappen im Dunkeln, während die Zukunft dieser Welt im Begriff ist, der Dunkelheit zu verfallen.\n\nUnd dennoch, die Sache könnte meinen Drachen die nötige Unterhaltung bieten.\n\nZeig mir diesen Schlüssel...", sourceObjectiveStatus = "unverified-source-field" }
quests[11680] = { id = 11680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jemanden unter seine Fittiche nehmen", description = "Der Schlüssel ist neu geschmiedet.\n\nNun hört meinen Rat, {race}. Vollbringt die Tat oder krepiert beim Versuch, denn sollte einem meiner Drachen auch nur eine einzige Schuppe gekrümmt werden, werde ich Euch persönlich zur Rechenschaft ziehen.\n\nHinfort mit Euch.", sourceObjective = "Gebt Kriegsmagier AnzimSalrands Schlüssel, wenn Ihr bereit seid, Evanor zu befreien.\n\nBereitgestellter Gegenstand:", completion = "Das ist es - der Schlüssel ist unser!", sourceObjectiveStatus = "unverified-source-field" }
quests[11681] = { id = 11681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evanor retten", description = "Endlich greifen wir an!\n\nSobald wir den Platz gesäubert haben, werde ich den Schlüssel verwenden.\n\nIhr müsst dafür sorgen, dass Lady Evanor sicher ist, nachdem sie befreit wurde.\n\nBeeilt Euch, lasst uns losfliegen!", sourceObjective = "Anzim vom Bernsteinflöz möchte, dass Ihr gemeinsam mit seinen Kriegsmagiern losfliegt, um Lady Evanor auf der Beryllspitze zu befreien. Danach sollt Ihr Euch bei Ihr im Magierturm auf dem Bernsteinflöz melden.", completion = "Eure Heldentaten werden nicht vergessen werden, {class}.\n\nBitte, nehmt dies und habt meine aufrichtige Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[11682] = { id = 11682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachengespräche", description = "Ich bin mir über Eure jüngsten Taten im Klaren, {name}, und möchte Euch noch einmal dafür danken.\n\nWas diese örtliche Bedrohung angeht, haben wir alles erfahren, was wir über sie erfahren können. Doch nun zu wichtigeren Angelegenheiten...\n\nAzeroth braucht Euch. Die Region gleich westlich von hier ist das Zentrum einer ernsten Krise.\n\nIch werde Lord Surristrasz über die Details in Kenntnis setzen. Ihr müsst umgehend mit ihm sprechen.\n\nViel Glück, <Freund/Freundin> von Dalaran.", sourceObjective = "Lady Evanor hat Euch ausgesandt, um mit Surristrasz vom Bernsteinflöz zu sprechen.", completion = "So, {race}. Wir werden wieder miteinander sprechen.\n\nWenn ich meinen Bericht erzählt habe, werdet Ihr Euch wünschen, ihn nie gehört zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11683] = { id = 11683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefallene Nekropole", description = "Von der gefallenen Nekropole im Westen kann man nur annehmen, dass sie noch immer voll von Schergen der Geißel ist.\n\nWährend Ihr in Talramas seid, {class}, möchte ich Euch bitten, alle Diener des Lichkönigs zu erledigen, die Ihr dort und in den umgebenden Teichen finden könnt.", sourceObjective = "Vernichtet bei den Eiterteichen und in Talramas 20 Diener der Geißel jeglicher Art. Kehrt dann zur Weisen Hochmesa zurück, welche sich gleich südlich der Höhlen des Todes befindet.", completion = "Habt Dank, {name}.\n\nDer Lichkönig und seine Geißel liegen auf Nordend wie eine Pest. Wir dürfen nicht ruhen, ehe alle vollkommen vernichtet sind und wir ihm den Garaus gemacht haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[11684] = { id = 11684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufspüren der Schlundlöcher", description = "Könnt Ihr die Beben in der Erde spüren?\n\nDie Neruber der Geißel bewegen sich tief unter der Erde. Sie sind im Südwesten, in den Geysirfeldern, wieder hervorgekommen und schikanieren die von Häuptling Orkan ausgeschickten Patrouillen.\n\n<Der Taunkaälteste bietet Euch eine abgenutzte Karte an.>\n\nVielleicht kann ein Einzelner dort siegen, wo die Patrouillen versagt haben. Nehmt dies mit Euch zu den Geysirfeldern und tragt die Positionen der nerubischen Schlundlöcher ein.", sourceObjective = "Großvater Mahan in Taunka'le möchte, dass Ihr die Karte der Geysirfelder nehmt und die Positionen des südlichen, des nordwestlichen und des nordöstlichen Schlundlochs eintragt.", progress = "Habt ihr die Positionen der Schlundlöcher eingetragen?", completion = "<Großvater Mahan nimmt die Karte entgegen, bewegt sich aber kein Stück, um sie zu untersuchen...>\n\nEure Informationen werden wir später einsetzen können, wenn wir bereit sind, den Plan umzusetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11685] = { id = 11685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz der Elemente", description = "Jetzt, da wir die genaue Position der Schlundlöcher der Neruber kennen, können wir diese einstürzen lassen, um die Offensive der Geißel zum erliegen zu bringen und ihre Streitkräfte hart zu treffen. Windzähmerin Barah kennt einen Weg, Elementare zu zügeln, um die von den Nerubern benutzten Tunnel zu zerstören, doch sie wird Eure Hilfe benötigen.\n\nSüdöstlich des Dorfes, nahe der Küste hinter den Gefrorenen Weiten werdet Ihr eine Region finden, die von gefrorenen Erdelementaren beherrscht wird. Die Herzen dieser Elemente sind genau das, was Windzähmerin Barah braucht.", sourceObjective = "Bringt 5 Elementarherzen zu Windzähmerin Barah in Taunka'le.", progress = "Großvater Mahan hat mir mitgeteilt, dass Ihr zugestimmt habt, dabei zu helfen, die Tunnel zum Einsturz zu bringen.", completion = "Das sollte ausreichen, um den Kern eines mächtigen Elementar zu erschaffen, doch Stein allein wird meinem Elementar kein Leben einhauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11686] = { id = 11686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Höfe des Kriegshymnenklans", description = "Luthers Notizen nach benutzt die Geißel diesen Ort jetzt als Brutstätte für die Monster, die man über die Felder trampeln sieht.\n\n<Ickoris schaudert es.>\n\nDiese Monster waren einst Orcs... Tauren...\n\nBevor wir einen Plan schmieden können, benötigen wir mehr Informationen. Ich möchte, dass Ihr drei Stätten untersucht, die von der Geißel heimgesucht werden: die Kornkammer des Kriegshymnenklans südwestlich von uns, Torps Bauernhof direkt in unserem Westen und der alte Schlachthof des Kriegshymnenklans nördlich von hier.\n\nKehrt zu mir zurück, sobald Ihr diese ausgespäht habt.", sourceObjective = "Schattenpirscher Ickoris bei den Höfen des Kriegshymnenklans möchte, dass Ihr die Kornkammer des Kriegshymnenklans, Torps Bauernhof und den Schlachthof des Kriegshymnenklans ausspäht.", completion = "Das ist weitaus schlimmer als das, was in Luthers Tagebuch stand. Dieser Ort wimmelt von Schergen der Geißel und sie infizieren alles, was sie anfassen.\n\n<Ickoris nickt.>\n\nEs wird noch schlimmer - wenn man sich das überhaupt vorstellen kann...", sourceObjectiveStatus = "unverified-source-field" }
quests[11687] = { id = 11687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Doktor und der Lichfürst", description = "Es gibt zwei... die... getötet... werden müssen.\n\nDer Doktor und... der Lichfürst... sind... dort oben. Findet sie... vernichtet sie… bevor...\n\n... es... zu spät ist...", sourceObjective = "Vernichtet Doktor Klingengrinser und Lichfürst Frostwinter und kehrt anschließend zur Weisen Hochmesa zurück. Sie befindet sich gleich südlich der Höhlen des Todes.", completion = "Borstenhorn ist tot?!\n\nIch hätte ihn niemals alleine dorthin gehen lassen dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11688] = { id = 11688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdammte, dreckige Schweine", description = "Seht sie Euch nur an! Meine wunderschönen Kodos können sich nicht gegen diese dreckigen Schweine verteidigen, sie sind hilflos! Ihr müsst mir etwas Zeit verschaffen, {race}. Ich denke, ich kann die Kodos von dieser Krankheit heilen, aber Ihr müsst diese untoten Schweine von ihnen fern halten, sonst bleibt kein Kodo mehr übrig, um geheilt zu werden!\n\nBewegt Euch da raus und bringt diese Schweine unter die Erde - dauerhaft!", sourceObjective = "Bauer Torp bei den Höfen des Kriegshymnenklans möchte, dass Ihr 10 untote Schweine tötet.", progress = "Ich brauche mehr Zeit! Haltet diese Schweine von meinen Kodos fern!", completion = "Ich glaube, ich bin soweit, {race}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11689] = { id = 11689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlechte Nachrichten überbringen", description = "Die Großmutter wird davon erfahren müssen, {name}.\n\nWürdet Ihr bitte nach Taunka'le zurückkehren? Sagt Ihr, dass ich bald nachkommen werde.", sourceObjective = "Sprecht mit Großmutter Taiga in Taunka'le.", completion = "Welch Nachricht überbringt Ihr mir von Hochmesa?\n\n<Ihr erklärt, was Ihr wisst, und überbringt der Großmutter die schlechten Nachrichten über Fernläufer Borstenhorn.>\n\nMein... mein Enkel!\n\n<Die Großmutter gibt sich Mühe, die Fassung zu wahren.>\n\nEr starb einen ehrenhaften Tod, den Tod eines Taunka!\n\nIhr wart der Letzte, der bei ihm gewesen ist, {name}. Also soll er auf ewig ein Teil von Euch sein. Habt meinen Dank dafür, seine letzten Wünsche erfüllt zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11690] = { id = 11690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt sie lebend zurück", description = "Nehmt diese Reittrense, {name}. Ihr werdet merken, dass ich einen kleinen Medizinspender in das Mundstück eingearbeitet habe. Das Ding wird die Infektion heilen, sobald der Kodo darauf beißt. Sobald Ihr sie geheilt habt, müsst Ihr sie nach Hause reiten. Sie werden nicht bei Kräften sein, also müsst Ihr sie sanft hierher bewegen.\n\nBringt mir meine Babys zurück, {name}!\n\nEins noch, Ihr habt 10 Minuten! Das Gegenmittel im Inneren der Trense bleibt nur so lange wirksam.", sourceObjective = "Bauer Torp bei den Höfen des Kriegshymnenklans möchte, dass Ihr 8 infizierte Kodobestien rettet.", progress = "Holt sie aus diesen von der Geißel verseuchten Feldern!", completion = "Ihr seid ein wahrer Held, {name}. Ohne Euch wären meine Kodos da draußen gestorben. Ihr habt meinen Dank und den Dank aller Soldaten und Reisenden, die diese Kodos benutzen werden, um unsere Stellung in Nordend zu stärken!", sourceObjectiveStatus = "unverified-source-field" }
quests[11691] = { id = 11691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschwört Ahune", description = "Ich und meine Schamanen haben all unsere Kräfte für die Schlacht mit dem Frostfürsten gesammelt. Ihr werdet die Faust der Erdenmutter sein, {name}.\n\nNehmt dieses Magmatotem und benutzt es in der Nähe des Eisbrockens im Nordosten. Ahune leitet seine Kraft durch diesen Brocken. Unsere Hoffnung ist, dass das Totem seine Verbindung mit der Elementarebene durchtrennen wird.\n\nWenn wir Glück haben, dann könnten wir ihn vielleicht besiegen.\n\nMacht Euch bereit, {name}. Wenn Ahune uns gegenübersteht, wird sein Zorn gewaltig sein.", sourceObjective = "Bringt dieses Magmatotem des Irdenen Rings zum Eisbrocken.", progress = "Dieser Eissplitter lässt das tiefe  Rumpeln und Knacken gewaltiger Gletscherzungen erklingen. Seine Kälte lässt Eure Gedanken erstarren und treibt sie in einen leblosen, endlosen Winter.", completion = "Das Magmatotem zerbirst in drei einzelne Flammen, als Ihr es in die Nähe des Eisbrockens bringt. Der Brocken schimmert - und löst sich anschließend in Luft auf...", sourceObjectiveStatus = "unverified-source-field" }
quests[11692] = { id = 11692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bei Bixie einchecken", description = "Ihr seid <ein gemachter Held/eine gemachte Heldin>. Ich hab' noch ein anderes Problem!\n\nMeine Chefin Tinky ist gemeinsam mit Bixie Zangkeuler nach Osten gegangen und ich bekomme das Sendesignal von diesem Dings einfach NICHT zum Laufen! Tinky ist die Einzige, die es reparieren kann, und es muss wirklich einwandfrei laufen.\n\nDenkt Ihr, dass Ihr sie finden könntet? Bixie meinte irgendwas davon, einem alten Magnatauren zu einem Ort namens 'Die Höhlen des Todes' folgen zu wollen.\n\nIch schätze mal, dass Ihr sie dort finden werdet.\n\nSprecht mit Kara Sternengala; sie wird dafür sorgen, dass man Euch dorthin bringt.", sourceObjective = "Mordle Zahnrad möchte, dass Ihr Bixie Zangkeuler aufsucht, die sich südlich der Höhlen des Todes befindet.", completion = "Womit kann ich dienen, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[11693] = { id = 11693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, großartig... verseuchte Magnatauren!", description = "Tinky und ich sind hierhergekommen, um Jagd auf einen alten Magnatauren zu machen. Offenbar sind diese Höhlen dort oben der Ort, den sie zum Sterben aufsuchen.\n\nAuf keinen Fall hatten wir gewusst, dass sie dort drin verseucht werden. Wir können hier keine umherstreunenden verseuchten Wesen gebrauchen - ist nicht gesund.\n\nSagt mal, wieso könnt Ihr nicht ein paar von den Dingern beseitigen, während ich versuche herauszufinden, wie es weitergehen soll?", sourceObjective = "Tötet 10 verseuchte Magnatauren. Kehrt anschließend zu Bixie Zangkeuler südlich der Höhlen des Todes.", completion = "Gute Arbeit, aber ich würde mir an Eurer Stelle bei nächster Gelegenheit eine Dusche gönnen.\n\nNa, dann lasst uns mal das Problem hier draußen richtig anpacken.", sourceObjectiveStatus = "unverified-source-field" }
quests[11694] = { id = 11694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irgendetwas geht in diesen Höhlen vor", description = "Während Ihr Euch also um diese verseuchten Biester gekümmert habt, hab' ich mich mal in diesen Höhlen dort oben umgesehen.\n\nSie werden von Kultisten verseucht!\n\nDa gibt es einen Kessel, in dem sie irgend so ein übles Zeug brauen. Ich hab' ein Pulver bei mir, das ich normalerweise als Gegengift verwende und das ich mit ein paar anderen Sachen vermischt habe. Ich denke, dass sich damit das Gebräu neutralisieren lässt!\n\nNehmt es mit Euch, geht zu einer der Höhlen dort oben und seht nach, ob es funktioniert.", sourceObjective = "Bixie Zangkeuler möchte, dass Ihr Bixies Desinfektionspuder in den Seuchenkessel in den Höhlen des Todes schüttet, um ihn zu neutralisieren. Bixie schleicht gleich südlich der Höhlen des Todes herum.", progress = "Die Zeit verrinnt, {class}. Das Letzte, was wir gebrauchen können, sind verseuchte Magnatauren, gegen die wir kämpfen müssen.\n\nDie Normalen sind schon schlimm genug!", completion = "Ich hab' gewusst, dass etwas in Euch steckt. Nun, es gibt da noch eine Sache, um die Ihr Euch für mich kümmern müsst.", sourceObjectiveStatus = "unverified-source-field" }
quests[11695] = { id = 11695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Horn des Elementarfurors", description = "Ich kann aus diesen Stücken leblosen Steins das Ebenbild eines Elementars erschaffen, doch ihm Leben einzuhauchen, ist etwas anderes. Um das zu tun benötigen wir Hilfe und ein bisschen Glück.\n\nDer Legende nach soll einst ein großer Held der Taunka auf der Suche nach einem uralten Artefakt namens \"Horn des Elementarfurors\" gewesen sein. Ich werde Euch eine Schriftrolle mit der Abschrift dieser Geschichte leihen. Ich weiß zwar nicht, ob etwas Wahres an ihr dran ist, doch uns bleibt nichts anderes übrig. Falls die Legende stimmen sollte, dann könnten die Hornteile auf den Flutebenen nördlich und südwestlich des Dorfes zu finden sein.", sourceObjective = "Tötet Häuptling Burbelgobbel und Häuptling Gurgelboggel, nehmt ihnen die untere und obere Hornhälfte ab und bringt sie zu Windzähmerin Barah in Taunka'le.", progress = "Konntet Ihr das Horn finden? Ist die Legende wahr?", completion = "<Barah nimmt beide Hälften des Horns entgegen und versucht, sie zusammenzufügen.>\n\nSturmhuf wäre stolz auf Euch, {name}. Vielleicht werde ich, wenn wir uns um die Geißel gekümmert haben, das Horn mit auf eine Pilgerfahrt zu Sturmhufs Grab nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11696] = { id = 11696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ahune ist hier!", description = "{name}, Eure Gegenwart ist ein Segen. Ahune befindet sich in den Höhlen und sammelt Kräfte für seinen Angriff. Truppen des Irdenen Rings wurden vorausgeschickt, doch alleine werden sie ihn nicht besiegen können.\n\nErkundet die Höhlen, {name}. Findet unsere Schamanen des Irdenen Rings und meldet Euch bei ihrer Anführerin, Luma Himmelsmutter. Mit vereinten Kräften werden wir Ahune vielleicht besiegen können, bevor es zu spät ist.", sourceObjective = "Findet Luma Himmelsmutter in den Sklavenunterkünften.", completion = "Ahunes Kälte breitet sich in diesen Höhlen aus, {name} - ein Vorgeschmack des eisigen Todes, der uns erwarten würde, sollte er seine volle Stärke erlangen. Erdenmutter sei Dank, dass sie Euch gesandt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[11697] = { id = 11697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mist, Tinky ist in die Nekropole gelaufen!", description = "Ich habe Tinky gewarnt, nicht alleine loszuziehen, doch sie musste ja einfach die verunglückte Nekropole im Westen untersuchen.\n\nIch bin 100% sicher, dass diese Kultisten aus diesem Ding rausgekommen sind, weshalb ich jetzt 100% sicher bin, dass Tinky in Schwierigkeiten steckt!\n\nSie ist die Top-Ingenieurin der Landebahn. Ohne sie sind wir verdammt!\n\nIch würde ja selber gehen, doch eines dieser Dinger hat mir schon wieder Fesseln angelegt, bevor ich verschwinden konnte. {name}, falls sie irgendwer da rausholen kann, seid Ihr es!", sourceObjective = "Sucht Tinky Dochtpfiff im Inneren von Talramas.", completion = "Hey Ihr! Wer seid Ihr?\n\nBixie hat Euch geschickt? Ausgezeichnet, dann holen wir mich mal hier raus!", sourceObjectiveStatus = "unverified-source-field" }
quests[11698] = { id = 11698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Man kann auch gleich die Geißel auslöschen", description = "Falls die Kultisten oben in diesen Höhlen den Absturz überlebt haben, dann kann man nur annehmen, dass die gefallene Nekropole im Westen noch immer voll von Schergen der Geißel ist. Es gibt sie bestimmt auch massenweise bei den Teichen, die sich dort befinden!\n\nWährend Ihr in Talramas seid, {class}, meint Ihr, Ihr könntet alle Lakaien des Lichkönigs, die Ihr dort findet, platt machen?", sourceObjective = "Vernichtet bei den Eiterteichen und in Talramas 20 Diener der Geißel jeglicher Art. Kehrt dann zu Bixie Zangkeuler zurück, welche sich gleich südlich der Höhlen des Todes befindet.", completion = "Danke, {name}.\n\nDer Lichkönig und seine Geißel sind wirklich Furcht einflößend, doch wir können nicht ruhen, ehe sie nicht in frischen Gräbern ruhen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11699] = { id = 11699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bin in diesem verdammten Käfig gefangen... aber nicht mehr lange!", description = "Die Kultisten haben mich in diesen Käfig gehext und er hat kein Türgitter. Sie wussten jedoch nicht, dass ich der Hauptingenieuer für Transmaterie auf der Landebahn bin!\n\nMit Eurer Hilfe und ein wenig Schmalz werde ich schon bald hier raus sein.\n\nIch werde einen Motorkernkristall von einem der Ghule hier benötigen, ein magisches Gyroskop ihrer Doktoren und einen Geißelsteuerungsstein von ihrem Lichfürsten ganz oben.\n\nMit dem ganzen Zeug sollte ich ein Portalgerät basteln können, mit dem ich auf gnomische Art entkommen und wieder zu Kurbelzisch gelangen kann!", sourceObjective = "Findet einen Motorkernkristall, ein magisches Gyroskop und einen Geißelsteuerungsstein. Liefert die Gegenstände anschließend bei Tinky Dochtpfiff in Talramas ab.", progress = "Habt Ihr das ganze Zeug mitgebracht?", completion = "Hervorragend! Jetzt nur noch eine Modifikation hier und eine kleine Änderung da...", sourceObjectiveStatus = "unverified-source-field" }
quests[11700] = { id = 11700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst es Bixie wissen", description = "Mein böser Zwilling ist irgendwo da draußen.\n\nIch bin mir ziemlich sicher, dass sie noch nicht zurück bei der Landebahn ist. Vielmehr, wo immer es sie hin verschlagen hat, sie ist jetzt an einem Ort, an dem es viel kälter ist als hier. Doch ich konnte sie nur für einen kurzen Moment \"fühlen\".\n\nNun gut, ich werde das Ding neu konfigurieren und mich selbst schon bald zurück zur Landebahn teleportieren. Meint Ihr, Ihr könntet in der Zwischenzeit nach Osten zu Bixie gehen und sie wissen lassen, dass ich sie dort treffen werde?\n\nDanke, {name}!", sourceObjective = "Sprecht mit Bixie Zangkeuler gleich südlich der Höhlen des Todes.", completion = "Tinky hat einen bösen Zwilling?!\n\nNun, wenn sie sagt, dass es ihr gut geht und dass sie bald selbst zurück zur Landebahn kommt, soll mir das Recht sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[11701] = { id = 11701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zum Landeplatz", description = "Nun gut, ich denke, dass ich mich auch wieder auf den Weg zurück zum Landeplatz mache. Mit meiner Verletzung am Bein werde ich sicherlich ein wenig länger brauchen.\n\nSagt mir, denkt Ihr, dass Ihr vor mir dort ankommen und dem alten Kurbelzisch die guten Neuigkeiten überbringen könntet? Ich wette, dass Euch auch eine Belohnung winken wird.\n\nDanke, {name}!", sourceObjective = "Sprecht mit Kurbelzisch Vollgas auf der Landebahn Kurbelzisch in der Boreanischen Tundra.", completion = "Das sind Neuigkeiten, {name}. Ein Wunder, dass bei all den Problemen hier draußen der Landeplatz nicht schon längst von der Landkarte getilgt wurde.\n\nDoch Dank Euch, gibt es nun einen Gegner weniger, um den wir uns den Kopf zerbrechen müssen.\n\nFür Anlässe wie diesen hier habe ich ein paar spezielle Gegenstände aufgehoben. Wieso sucht Ihr Euch nicht einfach einen aus?", sourceObjectiveStatus = "unverified-source-field" }
quests[11702] = { id = 11702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "König Mrgl-Mrgl", description = "Das wiad sich schräg anhöan, {class}, aber da wiad es einen Murloc geben, dea fragen wiad, ob wia ihm helfen könn'n!\n\nMan nennt ihn König Mrgl-Mrgl, dea Anführa dea Wintaflossen. Er und seine Leute wurden aus dem Dorf gejagt und sie wollan, dass Ia kommt und ihn'n helft.\n\nIa findat ihn, wenn Ia nach Westan geht und de Klippen runterlauft. Ea hängt im Süden dea Zuflucht dea Winterflossen ab.", sourceObjective = "Sprecht mit König Mrgl-Mrgl. Dieser befindet sich in der Zuflucht der Winterflossen.", completion = "Endlich - Hilfe! Und dem Anschein nach Horde.\n\nDas passt... Eure Leute sind sehr geübt, wenn es ums Kämpfen geht. Davon werden wir jede Menge benötigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11703] = { id = 11703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gelangt zu Getry", description = "Der für die Entführung und Verwandlung unserer Hordesoldaten in untote Monster verantwortliche Agent der Geißel nutzt die nordwestliche Farm als Brutstätte. Schattenpirscher Getry hat die ganze letzte Woche die Machenschaften dieses Monsters verfolgt und ein paar entscheidende Informationen gesammelt, mit deren Hilfe wir die Bedrohung womöglich aus der Welt schaffen können.\n\nGelangt zu Getry und seht nach, ob Ihr verhindern könnt, dass dort am laufenden Band neue Diener der Geißel produziert werden. Ihr findet Getry bei dem verlassenen Turm an der nordwestlichen Grenze dieser Höfe.", sourceObjective = "Geht zu den Höfen des Kriegshymnenklans und findet Schattenpirscher Getry.", completion = "<Getry mustert Euch von Kopf bis Fuß.>\n\nDas ist alles, was Ickoris schicken konnte?", sourceObjectiveStatus = "unverified-source-field" }
quests[11704] = { id = 11704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "König Mrgl-Mrgl", description = "Das ist mal seltsam, {class}, aber da wird es einen Murloc geben, der Euch um Hilfe bitten wird!\n\nMan nennt ihn König Mrgl-Mrgl, der Anführer der Winterflossen. Es scheint, als hätte man seine Leute und ihn aus ihrem Dorf verjagt - nun wollen sie jemanden, der ihnen hilft.\n\nUnd dieser Jemand seid Ihr!\n\nIhr findet die Zuflucht der Winterflossen und den König in westlicher Richtung. Geht einfach die Straße entlang, bis Ihr die Klippen erreicht, und steigt sie in der Nähe des Kochenden Teiches hinab.", sourceObjective = "Sprecht mit König Mrgl-Mrgl. Dieser befindet sich in der Zuflucht der Winterflossen.", completion = "Endlich - Hilfe! Und dem Anschein nach Allianz.\n\nGut so... Eure Leute sind sehr geübt, wenn es ums Kämpfen geht. Davon werden wir jede Menge benötigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11705] = { id = 11705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Törichtes Unterfangen", description = "Das ist Wahnsinn. Wie kann man von uns erwarten, dass wir uns mit einem Nekrolord der Geißel und einer unbekannten Zahl an Gefolgsleuten anlegen?\n\n<Getry schluchzt.>\n\nWenn Ickoris Euch schickt, dann muss er Euch für große Taten in der Lage halten. Vielleicht verursacht Ihr hier und heute ja ein Wunder, was?\n\nWenn Ihr soweit seid, steigen wir hinunter und treten Varidus gegenüber.\n\nWenn wir es in einem Stück aus dieser Misere heraus schaffen, meldet Euch bei Höllschrei in der Kriegshymnenfeste.", sourceObjective = "Helft Getry dabei, Varidus den Flenser bei den Höfen des Kriegshymnenklans zu besiegen.\n\nFalls Ihr erfolgreich sein solltet, erstattet Garrosh Höllschrei Bericht.", completion = "Und Ihr seid siegreich zurückgekehrt, genau wie ich dachte! Ich habe es Saurfang ja gesagt, dass Ihr spitze seid.\n\n<Höllschrei grunzt besserwisserisch.>\n\nVielleicht wird das dem alten Hund zeigen, dass er nicht auf alles eine Antwort hat, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[11706] = { id = 11706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kollaps", description = "Ich habe Alluvius mithilfe des Horns des Elementarfurors erschaffen und gebunden. Geht zum südlichsten Schlundloch und lasst das Horn erschallen - er wird seinem Ruf gehorchen.\n\nDas Erdbeben, das Alluvius hervorrufen wird, sollte die nerubischen Tunnel zum Einsturz bringen und ihrem Flankenangriff ein Ende setzen. Ich wäre nicht überrascht, wenn sich der Hauptmann der Neruber nach dem Erdbeben zeigen würde. Sollte der Einsturz der Tunnel ihren Angriff nicht zum Halt bringen, würde ein Sieg über ihren Anführer in dieser Hinsicht sicherlich Erfolg haben.", sourceObjective = "Windzähmerin Barah in Taunka'le möchte, dass Ihr die nerubischen Schlundlöcher mithilfe des Horns des Elementarfurors zum Einsturz bringt und Fürst Kryxix besiegt.", progress = "Habt Ihr Alluvius losgelassen und den nerubischen Angriff zum Erliegen gebracht?", completion = "Eure Dienste gegen die Neruber haben den überwältigenden Ansturm der Geißel kurzzeitig zum Stillstand gebracht und gewähren uns eine Verschnaufpause. Dank Eurer Taten können wir die nördlich gelegene Festung der Geißel angreifen, ohne einen Angriff aus dem Westen fürchten zu müssen.\n\nWas das Horn angeht: Ich werde es einstweilen in sicheren Gewahrsam nehmen, bis wir seine Macht wieder benötigen. Sturmhuf hat sein Leben dafür gegeben, dieses Horn zu sichern, und wir können es uns nicht leisten, es noch einmal zu verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[11707] = { id = 11707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notruf", description = "Oh, gut, Ihr seid {name}, nicht wahr?\n\nWir benötigen heute wiedereinmal Eure Hilfe. Es geht genauso wie gestern um die Landebahn Kurbelzisch im Norden! Die Magnatauren und die Geißel... und die Pumpstation!\n\nEs ist verrückt, sag' ich Euch, verrückt!\n\nIhr müsst dorthin gehen und mit dem alten Vollgas sprechen - und zwar dalli!", sourceObjective = "Sprecht mit Kurbelzisch Vollgas auf der Landebahn Kurbelzisch.", completion = "Wie ich sehe, hat es Himmelhopper endlich mal geschafft, Hilfe zu schicken. Und nicht zu früh, möchte ich hinzufügen!\n\nWillkommen, Bruder, wir benötigen dringend Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[11708] = { id = 11708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mechagnome", description = "Nun, da Ihr hier seid, ist der Zeitpunkt gekommen, dass ich Euch die ganze Geschichte über das erzähle, was hier los ist.\n\nGeht nach draußen, sobald Ihr meinen Bericht gehört habt, und sprecht mit Jinky Flügelirre. Sie wird sich von da ab um alles kümmern.", sourceObjective = "Hört Euch Kurbelzisch Vollgas' Bericht an und sucht anschließend Jinky Flügelirre auf der Landebahn Kurbelzisch auf.", progress = "Tagchen.", completion = "Der Alte hat Euch zu mir geschickt, hm? Und er hat Euch alles darüber erzählt, was hier draußen vor sich geht?\n\nGut... dann packen wir mal die Sache an!", sourceObjectiveStatus = "unverified-source-field" }
quests[11709] = { id = 11709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nork Blutwahns Aufgabe", description = "Obgleich Ihr viel getan habt, um unsere Position hier in diesen gefrorenen Weiten zu festigen, lauern noch immer andere Gefahren in den Schatten. Ich möchte, dass Ihr Aufseher Nork Blutwahn helft, der im Internierungslager stationiert ist, welches gleich südöstlich der Kriegshymnenfeste liegt. Sucht ihn auf und bietet ihm Eure Hilfe beim Transport und beim Austausch der Gefangenen an.\n\nWegtreten, {name}.", sourceObjective = "Sprecht mit Aufseher Nork Blutwahn in der Kriegshymnenfeste in der Boreanischen Tundra.", completion = "<Nork spottet.>\n\nGefangene? Das sind keine Gefangenen. Das sind feige Hunde! Seht sie Euch nur an. Wusstet Ihr, dass jeder einzelne dieser gelbbäuchigen \"Soldaten\" vor unsere Tore kam und seine Waffen und seine Rüstung niedergelegt hat?\n\nNach dem zu urteilen, was wir gehört haben, werden diese Männer und Frauen entlassen und zurück nach Hause geschickt, wenn sie von uns gefangen werden.\n\n<Nork spuckt.>\n\nErbärmlich...", sourceObjectiveStatus = "unverified-source-field" }
quests[11710] = { id = 11710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist nur los mit der Transmaterie?", description = "Überall im Osten sind Ersatzteile verstreut: in den Siedenden Teichen, den Geysirfeldern... ach, was sag ich, wahrscheinlich sogar bis zur Pumpstation hin liegt das Zeugs rum. Bringt es alles wieder zurück. Vielleicht werde ich es dann hinbekommen, mit dem Ding auch jemanden von hier wegzuteleportieren, ganz abgesehen davon, dass ich noch die eingehenden Transmatierieanschlüsse ausrichten muss.\n\nIch würde ungern einen weiteren Unfall erleben...", sourceObjective = "Sammelt 15 Ersatzteile von Kurbelzisch und liefert sie an Mordle Zahnrad auf der Landebahn Kurbelzisch.", progress = "Wir werden 'ne Menge Ersatzteile brauchen, um dieses Ding am Laufen zu halten.\n\nBitte sagt mir, dass Ihr alles dabei habt, was wir benötigen.", completion = "Das ist großartig, {class}! Diese Teile sehen aus, als wären sie in einem brauchbaren Zustand.\n\nWenn ich jetzt nur herausfinden könnte, wie man eines dieser verfluchten Dinger repariert...", sourceObjectiveStatus = "unverified-source-field" }
quests[11711] = { id = 11711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angsthasenlieferung... unter 30 Minuten - ansonsten gratis", description = "Mit jedem Tag, der verstreicht, kommen mehr Deserteure an unser Tor. Wir haben einfach nicht genug Platz, um all diese Maden zusammenzupferchen. Ganz besonders dann nicht, wenn wir die Schweine bei Laune halten wollen.\n\n<Nork prustet vor Lachen.>\n\nIch möchte, dass Ihr einen der Feiglinge zur Kreuzung im Osten begleitet und diese Leuchtpistole abfeuert. Einer ihrer Hauptmänner wird auftauchen, sobald die Allianz das Leuchtsignal sieht, und Euch den Feigling abnehmen.\n\nMeldet Euch bei Späher Tungok auf der Oststraße, nachdem die Lieferung stattgefunden hat.", sourceObjective = "Bringt den Deserteur der Allianz zur Kreuzung östlich der Kriegshymnenfeste und feuert die Leuchtpistole des Kriegshymnenklans ab, um der Allianz ein Zeichen zu geben.\n\nMeldet Euch bei Späher Tungok, nachdem die Übergabe des Deserteurs der Allianz erfolgreich abgeschlossen wurde.", completion = "Gute Arbeit, {name}. Das ist ein dreckiger, unnützer Allianzmistkerl weniger, den wir versorgen müssen...\n\nFalls Ihr noch mehr Arbeit wollt, die Tauren und Blutelfen hier in der Nähe bräuchten ein wenig Hilfe.\n\nNatürlich haben wir hier draußen auch unsere eigenen Probleme, mit denen wir uns herumschlagen müssen...", sourceObjectiveStatus = "unverified-source-field" }
quests[11712] = { id = 11712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verflucht nochmal!", description = "Wenn Ihr dem alten Mann zugehört habt, wisst Ihr, dass manche Gnome dort draußen manipuliert wurden. Ritzelmeister Mechazod hat sie mit etwas infiziert, das den 'Fluch des Fleisches' neutralisiert, und nun sind sie Roboter!\n\nWir meinen, einen Weg gefunden zu haben, sie wieder mit einem Fluch zu belegen, der sie wieder normal macht. Dazu müsst Ihr diese fluchrekursive Transmaterieinjektion auf die Leichen der Mechagnome, über die Ihr stolpert, anwenden.\n\nWir hoffen, dass dieses Zeugs sie heilen und es uns erlauben wird, sie wieder hierher zurückzuteleportieren.\n\nWas meint Ihr dazu, {name}?", sourceObjective = "Jinky Flügelirre bei der Landebahn Kurbelzisch möchte, dass Ihr die fluchrekursive Transmaterieinjektion auf 6 der Mechagnome von Kurbelzisch anwendet.", completion = "Ihr habt es geschafft... es hat funktioniert!\n\nIch kann es gar nicht glauben, dass Ihr so viele retten konntet. Wir können uns glücklich schätzen, Euch hier bei uns zu haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[11713] = { id = 11713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufspüren der Schlundlöcher", description = "Kurbelzisch hat ein Luftüberwachungsteam losgeschickt, um die Schlundlöcher der Neruber im Süden der Geysirfelder zu kartieren, doch das ist noch nicht zurückgekehrt. Ich kann nicht länger auf die Informationen warten, deshalb brauche ich jemanden, der zu Fuß die Schlundlöcher sucht.\n\nIch verstehe die damit verbundenen Gefahren und werde Euch dementsprechend entschädigen. Nehmt diese Karte mit und tragt die entscheidenden Informationen über die Schlundlöcher ein, auf die Ihr dort draußen trefft.", sourceObjective = "Abner Zischeldrill auf der Landebahn Kurbelzisch möchte, dass Ihr die Karte der Geysirfelder nehmt und die Positionen des südlichen, des nordwestlichen und des nordöstlichen Schlundlochs eintragt.", progress = "Habt ihr die Positionen der Schlundlöcher eingetragen?", completion = "<Abner nimmt die Karte entgegen und studiert sie genau.>\n\nGroßartig! Das ist alles, was wir an Informationen brauchen, um mit der Operation zu beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11714] = { id = 11714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungeziefer vertilgen", description = "Hättet Ihr vielleicht Interesse, mir dabei zu helfen, diese Felder zu säubern? Sie sind mit dreckigen kleinen Rattenmenschen übersät! Kobolde, Schneebolde oder wie auch immer Ihr sie nennen wollt, sie sind über den ganzen verdammten Ort verstreut. Der Gestank alleine ist die reinste Hölle!\n\nKümmert Euch für mich um das Ungeziefer und ich werde dafür sorgen, dass es sich für Euch lohnt, {name}.", sourceObjective = "Späher Tungok in der Blutsporenprärie in der Boreanischen Tundra möchte, dass Ihr 8 Blutsporenernter, 5 Blutsporenfeuerteufel und 2 Blutsporenröster tötet.", completion = "Gute Arbeit, {name}! Ich danke Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[11715] = { id = 11715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Öl für das Projekt", description = "Ich möchte eine Maschine bauen, die die Tunnel zum Einsturz bringt, welche die Geißel benutzt, um ihre Neruber einzusetzen. Aber da die Hauptbohrplattform außer Betrieb ist, müssen wir uns irgendwie anders Treibstoff für das Gerät besorgen.\n\nDraußen in den Geysirfeldern im Südosten gibt es kleine Öllachen, die entfernt von der Hauptplattform aus dem Boden quellen. Wenn Ihr genug Öl von diesen Lachen besorgen könnt, kann ich Treibstoff herstellen, um die Maschine zu betreiben.\n\nSetzt einfach den Sammler in der Nähe der Plattform ein und er wird das Öl in seinen Tank pumpen.", sourceObjective = "Abner Zischeldrill auf der Landebahn Kurbelzisch möchte, dass Ihr mit dem tragbaren Ölsammler 8 Fässer Öl sammelt.", progress = "Habt Ihr den Treibstoff?", completion = "<Abner beginnt den Öltank des Sammlers zu leeren.>\n\nDas per Hand zu destillieren ist schwierig, doch ich werde das schon bald erledigt haben. In der Zwischenzeit brauchen wir noch eine weitere Komponente, um die Maschine fertig zu stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11716] = { id = 11716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wundersamen Blutsporen", description = "Wir sind Zeugen von etwas Außergewöhnlichem, {race}. Ein paar Schritt weit entfernt von uns existiert ein ganzes Ökosystem, das noch nicht entdeckt wurde! Ich vermute, dass die Blutsporenpflanze die Natur hier zum Sprießen bringt.\n\nIch habe ein wenig Blütenstaub der nahe gelegenen männlichen Blutsporenpflanze gesammelt, doch zur Bestäubung fehlen mir noch die weiblichen Rezeptoren. Besorgt mir einen Scheffel der Blutsporenkarpelle. Ihr könnt sie in der Nähe der größeren Pflanzen finden, die uns umgeben.\n\nNehmt Euch jedoch vor ihren Wächtern in Acht! Die Kobolde werden sie nicht ohne Weiteres aufgeben!", sourceObjective = "Blutmagierin Laurith in der Blutsporenprärie in der Boreanischen Tundra möchte, dass Ihr 10 Blutsporenkarpelle beschafft.", progress = "Die Versuche müssen weitergeführt werden!", completion = "Herrlich! Einfach herrlich!\n\n<Laurith trägt ein wenig Blütenstaub auf eines der Blutsporenkarpelle auf und spricht eine Beschwörungsformel.>\n\nHmpf... ich verstehe nicht. Außer... Aber natürlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[11717] = { id = 11717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pollen von den Motten besorgen", description = "Es liegt auf der Hand! Die Blutsporenmotten sind für die Bestäubung dieser Ebenen verantwortlich. Es muss etwas aus dem Stoffwechsel der Motten sein, das als Katalysator für die Funktion dieser Pollen dient. Es fängt jetzt alles an, einen Sinn zu ergeben, {name}. Deshalb töten die Kobolde die Motten nicht, sondern beschützen sie so gut sie können! Diese dreckigen, kleinen Ratten haben das durchschaut!\n\nNun, dann müssen wir uns einfach unsere eigenen Mottenpollen besorgen! Was meint ihr dazu? Besorgt Ihr mir welche im Namen der Wissenschaft?", sourceObjective = "Blutmagierin Laurith in der Blutsporenprärie in der Boreanischen Tundra möchte, dass Ihr 5 Pollen von Blutsporenmotten besorgt.", progress = "Die Pollen sind der Schlüssel!", completion = "Ah-ha!\n\n<Laurith sprenkelt die Mottenpollen über die Blutsporenkarpelle.>\n\nSeht Euch das an!", sourceObjectiveStatus = "unverified-source-field" }
quests[11718] = { id = 11718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Bot im Mammutpelz", description = "Ich habe die Grundstruktur eines alten Bots so rekonfiguriert, dass er ein Erdbeben auslösen wird, das stark genug ist, die Tunnel zum Einsturz zu bringen. Doch die Maschine ist empfindlich gegenüber Nordends beißender Kälte.\n\nIch habe einen Weg gefunden, ihn mit den dicksten Bälgen einheimischer Mammuts zu isolieren. Sie streifen auf den Ebenen südlich der Landebahn und in der Nähe der Geysirfelder herum. Bringt genug Bälge mit, um die Maschine fertigzubauen und sie auf die Neruber loszulassen!", sourceObjective = "Abner Zischeldrill auf Landebahn Kurbelzisch möchte, dass Ihr ihm 6 dicke Mammutbälge bringt.", progress = "Bringt mir diese Bälge so schnell wie möglich! Ich werde die Maschine ohne sie nicht fertig stellen können!", completion = "<Abner inspiziert die Bälge. Der aufgewirbelte Staub bringt ihn zum Husten.>\n\nKörperhygiene wird bei diesen Tieren wohl nicht besonders groß geschrieben? Einige von diesen Fellen sind völlig verdreckt. Nun, ich sollte wohl besser damit anfangen, sie zu reinigen. Ist ja nicht so, dass hier irgendwer Zeit übrig hätte - oh nein.", sourceObjectiveStatus = "unverified-source-field" }
quests[11719] = { id = 11719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein geeignetes Versuchsobjekt", description = "<Laurith mustert Euch von Kopf bis Fuß.>\n\nSo, wir haben also diese bestäubte Blutsporenblume hier, aber niemanden, an dem wir ihre Wirkung ausprobieren könnten. Sagt mir, wäret Ihr vielleicht daran interessiert, das hier auf Eure Haut zu reiben und mich dabei zusehen zu lassen, was passiert? Was könnte schon Schlimmes dabei passieren?\n\nKeine Sorge, {name}! Schmiert Euch einfach ein wenig von dem hier ins Gesicht.", sourceObjective = "Blutmagierin Laurith auf der Blutsporenprärie in der Boreanischen Tundra möchte, dass Ihr die bestäubte Blutsporenblume verwendet und sie dabei zusehen lasst, was passieren wird.", progress = "Habt keine Angst.", completion = "Ur Machthorn wird entzückt sein! Das ist besser, als ich es je erwartet hätte!\n\nWomöglich ist es an der Zeit, dass ich Euch die Wahrheit erzähle.", sourceObjectiveStatus = "unverified-source-field" }
quests[11720] = { id = 11720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Invasion von Gammut", description = "Höllschrei hat Machthorn und mich mit der entmutigenden Aufgabe betraut, die Magnatauren an der südlichen Front der Kriegshymnenfeste auszurotten. Mit uns kam ein kompletter Zug erfahrener Hordesoldaten. Unser erster Vorstoß in die nahe gelegenen Magnataurenhöhlen erwies sich als recht erfolglos, da unser kompletter Trupp von den Verteidigern der Höhlen ausgelöscht wurde. Wir sind die einzigen, die übrig sind...\n\nWir sind weder Wissenschaftler noch Forscher. Wir sind Soldaten der Horde, so wie Ihr...\n\nSprecht jetzt mit Ur Machthorn.", sourceObjective = "Sprecht mit Ur Machthorn in der Blutsporenprärie in der Boreanischen Tundra.", completion = "Die Blutsporen, die Ihr gesammelt habt, könnten uns einen Vorteil gegen die Magnatauren von Gammut verschaffen. Mit Eurer Hilfe versteht sich.", sourceObjectiveStatus = "unverified-source-field" }
quests[11721] = { id = 11721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gammutra der Peiniger", description = "Magnatauren leben in Rudeln, gleich den Löwen: ein oder zwei dominante Männchen und mehrere Weibchen gemeinsam mit ihrem Nachwuchs. Der Anführer von Gammut, der Magnataurenhöhle westlich von hier, wird Gammutra genannt. Es ist Gammutra, der über diese Magnataurenpopulation herrscht, also ist es auch Gammutra, den wir niederstrecken müssen, um jegliche Art des Aufruhrs durch die Magnatauren zu verhindern.\n\nNehmt diesen Beutel mit zerdrückten Blutsporen an Euch und geht nach Gammut. Schwächt Gammutra mithilfe der Blutsporen und erschlagt ihn! Bringt mir sein Haupt als Beweis.", sourceObjective = "Erschlagt Gammutra und bringt den Kopf von Gammutra zu Ur Machthorn in der Blutsporenprärie in der Boreanischen Tundra.", progress = "Das Pulver kann dazu verwendet werden, alle Magnatauren zu schwächen. Was auch der Grund dafür ist, weshalb das Rattenvolk in dieser Gegend es so gut behütet.", completion = "Ihr habt gute Arbeit geleistet, {name}! Würdet Ihr Laurith und mir die Ehre erweisen, zu Höllschrei zu gehen und ihm den Kopf des Biests zu präsentieren? Er wird äußerst zufrieden sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[11722] = { id = 11722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trophäen von Gammut", description = "Der Sieg der Horde ist nicht allein uns zu verdanken, {name}. Ihr wart es, <der/die> Ihr Euer Leben riskiertet, um die Blutsporen zu testen, und Ihr seid es gewesen, <der/die> Gammutra zu guter Letzt ein Ende bereitete.\n\nErweist uns die Ehre und kehrt zur Kriegshymnenfeste zurück, um Fürst Höllschrei den Kopf von Gammutra zu präsentieren.", sourceObjective = "Bringt den Kopf von Gammutra zu Garrosh Höllschrei in der Kriegshymnenfeste.", progress = "So schnell schon wieder zurück?", completion = "<Höllschrei hebt den Kopf von Gammutra mit einer Hand auf und spuckt in sein Gesicht.>\n\nSie werden es lernen, {name}... Sie werden es alle lernen. Mit der Horde ist nicht zu spaßen...", sourceObjectiveStatus = "unverified-source-field" }
quests[11723] = { id = 11723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setzt den Schüttlo-Rüttlo ein!", description = "Ich präsentiere Euch die Maschine, die uns vor der Bedrohung durch die Neruber beschützen wird!\n\n<Abner strahlt vor Stolz, als er Euch seinen fertigen Bot zeigt.>\n\nNehmt diese Fernsteuerung, geht zu einem der nerubischen Schlundlöcher auf den Geysirfeldern und aktiviert mit ihrer Hilfe den Schüttlo-Rüttlo 5000. Er wird dann den Rest von alleine erledigen.\n\nWundert Euch nicht, wenn das von ihm verursachte Erdbeben die Aufmerksamkeit eines nerubischen Anführers erregt. Genau genommen wäre es eine großartige Gelegenheit, der nerubischen Offensive den Rest zu geben.", sourceObjective = "Abner Zischeldrill auf der Landebahn Kurbelzisch möchte, dass Ihr mithilfe des Schüttlo-Rüttlo 5000 die Tunnel der Neruber zum Einsturz bringt und Fürst Kryxix besiegt.", completion = "<Abner hört Euch aufmerksam zu, während Ihr vom Erfolg des Schüttlo-Rüttlo 5000 und Euch berichtet.>\n\nKurbelzisch wird über die Nachrichten hocherfreut sein! Und wer weiß, vielleicht wird er sogar einen Mechaniker aus Euch machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11724] = { id = 11724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mächtiges Mottenomelett?", description = "Dieses Ei war jemandem offensichtlich sehr wichtig, wie die Leiche in der Nähe zeigt. Wenn man das Ei genauer betrachtet, merkt man, dass es bereits für den Versand in die Blutsporenprärie markiert war, an Blutmagierin Laurith. Das ist östlich von hier!\n\nNehmt das Ei und bringt es zur wartenden Blutmagierin.", sourceObjective = "Bringt das schwere leuchtende Ei zu Blutmagierin Laurith in der Blutsporenprärie in der Boreanischen Tundra.", progress = "Grüße!", completion = "Alkor ist Geschichte, wie? Eine Schande... Was das Ei angeht, so haben wir keine wirkliche Verwendung mehr dafür. Wir haben wesentlich größere Probleme, um die wir uns jetzt kümmern müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11725] = { id = 11725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Trudelflug", description = "Ich hätte die Mission selber fliegen sollen. Es ist nicht so, dass ich Trudelflug nicht vertrauen würde - ganz und gar nicht. Verdammt, er war der beste Flügelmann, mit dem ich je geflogen bin.\n\nNein, es ist nur so, dass ich eigentlich dafür zuständig bin, solch eine wichtige Mission zu fliegen.\n\nIch habe Trudelflug mit unserer schnellsten Aufklärerstaffel ausgesandt, um die Teiche weit im Süden und gleich westlich der nerubischen Schlundlöcher auszukundschaften.\n\nFindet Trudelflug, {name}.", sourceObjective = "Macht Iggy \"Trudelflug\" Zinkenwechsel auf den Geysirfeldern ausfindig.", completion = "Gnom sei Dank. Es war schrecklich.\n\nDa war ein greller Lichtblitz am Boden und das Nächste, woran ich mich erinnern kann, ist, dass die komplette Staffel im Begriff war, abzustürzen! Ich bin ziemlich schwer verletzt, hatte also nicht die Möglichkeit, die Absturzstelle nach anderen Überlebenden abzusuchen. Doch irgendetwas sagt mir, dass es nicht sehr viele geben wird.\n\n<Iggy verzieht sein Gesicht vor Schmerz.>\n\nWerdet Ihr mir dabei behilflich sein, meine Mission zu beenden?", sourceObjectiveStatus = "unverified-source-field" }
quests[11726] = { id = 11726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein klein wenig Würze", description = "Die Wölfe haben das Wrack nach dem Absturz durchwühlt und dabei wohl den Mikrofilm unserer Mission aufgefressen.\n\nIch habe einen Plan, wie wir diesen Mikrofilm wiederbeschaffen können, doch ich brauche Eure Hilfe, um das zu bewerkstelligen.\n\nGen Süden und Osten in den Flutebenen leben Kreaturen, die man die Gorloc nennt. Sie bereiten ihre Mahlzeiten mit üblen Gewürzen zu, die jede andere Kreatur grün anlaufen lassen würden. Wenn Ihr genug Gewürzbeutel von den Dampfrülpsern der Gorloc und den Watschlern der Gorloc sammelt, kann ich Euch daraus den Wolfsköder herstellen.", sourceObjective = "Iggy \"Trudelflug\" Zinkenwechsel bei den Siedenden Teichen möchte, dass Ihr 4 Gewürzbeutel der Gorloc sammelt.", progress = "Habt Ihr die Gewürzbeutel dabei?", completion = "<Iggy hält sich die Nase zu, als er die Gewürzbeutel leert, und spricht zu Euch mit einem nasalen Ton in seiner Stimme.>\n\nJetzt, wo wir alles Nötige haben, werde ich es mit den Notrationen vermischen, um daraus einen Köder für die Wölfe zu basteln.", sourceObjectiveStatus = "unverified-source-field" }
quests[11727] = { id = 11727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Zeit für Helden", description = "Es ist gut, Euch unter uns zu haben, {name}. Wir haben alle von Euren vergangenen Taten erfahren.\n\nWie Ihr wisst, ist König Wrynn dabei, große Armeen nach Nordend zu bewegen, die denen von Arthas begegnen sollen. Doch Armeen sind nichts ohne die Helden, die sie inspirieren und führen.\n\nIch möchte, dass Ihr <dieser Held/diese Heldin> für meine Männer seid. Kämpft an ihrer Seite gegen die Geißel, die unsere Festung belagert.\n\nMeldet Euch bei Unteroffizier Hammerberg außerhalb der inneren Burgwehr. Die Valianzfeste darf nicht fallen. Die Zukunft unserer Kampagne hängt davon ab.", sourceObjective = "Meldet Euch bei Unteroffizier Hammerberg in der Valianzfeste.", completion = "Bei Magnis Bart! Sieht aus, als wäre die Artillerie gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11728] = { id = 11728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lupus pupus", description = "Was auch immer Ihr macht, nehmt auf keinen Fall einen Happen von diesem Köder. Legt ihn einfach in der Nähe eines ölbeschmierten Wolfes. Wenn sie verzweifelt genug sind, den Mikrofilm zu fressen, dann werden sie sich wie wild auf den Köder stürzen, sobald sie ihn riechen.\n\nWartet einfach nur, bis die Dinge ihren natürlichen Lauf nehmen und sucht im... äh... Nebenprodukt nach dem Film.\n\nIch würde Euch ja meinen speziellen Lupus Pupus Spatus für den Job anbieten, aber ich habe ihn bei der Landebahn gelassen. Es tut mir leid, sagen zu müssen, dass Ihr die... ähhm... Suche auf die altmodische Art und Weise durchführen müsst.", sourceObjective = "Iggy \"Trudelflug\" Zinkenwechsel bei den Siedenden Teichen möchte, dass Ihr ihm 8 Mikrofilmteile bringt.", progress = "Habt Ihr den Mikrofilm beschaffen können?", completion = "<Iggy hält sich die Nase zu, als er den Mikrofilm entgegen nimmt.>\n\nIgittigitt! Nun ja, wir haben Absatz 8.2, Paragraph B des Notfallprotokolls entsprechend den Film wieder beschafft. Nichts im Protokoll deutet jedoch darauf hin, dass ich es putzen muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[11729] = { id = 11729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ultraüberschallschrauber", description = "Die Einheit, die Ihr soeben in ihre Bestandteile zerlegt habt, hatte das hier in ihrem Inneren.\n\nEs sieht ziemlich kompliziert aus... bei der Landebahn wird sicherlich jemand ein Auge drauf werfen wollen. Vielleicht Pfiffi Wackelspross?", sourceObjective = "Liefert den Ultraüberschallschrauber bei Pfiffi Wackelspross ab. Sie befindet sich auf der Landebahn Kurbelzisch.", completion = "Mein Schraubenzieher... Ihr habt meinen Schraubenzieher gefunden! Hab mich schon gefragt, wo ich das Ding verloren hab'.\n\nHmm, Ihr habt es im Inneren eines ihrer Roboter gefunden, meint Ihr? Das bringt mich auf eine Idee...", sourceObjectiveStatus = "unverified-source-field" }
quests[11730] = { id = 11730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister und Diener", description = "Der Ultraüberschallschrauber ist das ultimative Werkzeug, wenn es sich um das Bearbeiten von mechanischen Dingen dreht!\n\nGeht zurück zu den Teichen und zerlegt ein paar von Mechazods Robotern. Ihr müsst dann nur noch ihre Überreste mit dem Schraubenzieher bearbeiten und ich wette mit Euch, dass sie sich auf unsere Seite schlagen werden - zumindest für kurze Zeit.\n\nIch bin mir ziemlich sicher, dass er sich nicht auf die Mechagnome anwenden lässt, also könnt Ihr sie getrost ignorieren.\n\nOh, und falls die Roboter irgendwas dabei haben sollten, müsst Ihr es an Euch nehmen, bevor Ihr sie mit dem Schraubenzieher bearbeitet!", sourceObjective = "Programmiert mithilfe des Ultraüberschallschrauber 15 Roboter um und kehrt anschließend wieder zu Pfiffi Wackelspross bei der Landebahn Kurbelzisch zurück.\n\nAchtet darauf, die kaputten Roboter zu plündern, bevor Ihr sie umprogrammiert.", completion = "Juhuu! Und Ihr habt den Schraubenzieher in einem Stück zurückgebracht!\n\nDass wir diese Roboter umprogrammiert haben, wird sich noch als großer Vorteil im Kampf gegen Ritzelmeister Mechazod herausstellen. Ich meine, Ihr habt Euch eine Kleinigkeit dafür verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[11731] = { id = 11731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fackelwurf", description = "Ihr wollt also Feuerjongleur werden? Denkt Ihr, dass Ihr das Zeug dazu habt? Die Geschicklichkeit? Die Reflexe? ... den Mut? Wenn ja, dann wollen wir Euch mal auf die Probe stellen!\n\nNehmt diese Fackeln und rennt zum Freudenfeuer. Dort befinden sich Kohlenpfannen, über denen blinkende Markierungen schweben, die Ihr mit einer Fackel treffen müsst. Seid schnell! Um für einen Wurf Punkte zu bekommen, müsst Ihr die Fackel werfen, bevor die Markierung verschwindet!\n\nTrefft genug markierte Kohlenpfannen, bevor die Zeit abgelaufen ist, und kommt dann hierher zurück... um Eure nächste Lektion zu erhalten.", sourceObjective = "Gewinnt das Fackelwurfspiel und sprecht anschließend mit dem Feuerschluckmeister.", completion = "Gut gemacht! Die Lunte eines Feuerkreisels brennt schnell... doch Ihr werdet die Kunst des Feuerjonglierens noch schneller erlernen! Nun macht Euch bereit! Beim nächsten Test werdet Ihr so richtig ins Schwitzen kommen...", sourceObjectiveStatus = "unverified-source-field" }
quests[11732] = { id = 11732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entweiht dieses Feuer!", sourceObjective = "Entweiht das Freudenfeuer der Allianz im Arathihochland!", sourceObjectiveStatus = "unverified-source-field" }
quests[11733] = { id = 11733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise zum Riss", description = "Ich habe Eure Taten aufmerksam verfolgt, <Sterblicher/Sterbliche>. Tut nicht so, als wärt Ihr überrascht. Mit Sicherheit habt Ihr gespürt, wie mein Auge auf Euch ruht.\n\nDie Zeit ist nun gekommen, Euch nicht mehr gänzlich im Dunkeln herumtappen zu lassen. Ihr seid nun bereit, der nackten Wahrheit ins Auge zu blicken.\n\nDoch bevor Ihr die Geschichte hört, sollt Ihr erst erfahren, womit wir es zu tun haben.\n\nTrefft alle nötigen Vorbereitungen, {class}...", sourceObjective = "Surristrasz möchte, dass Ihr die Reise nach Kaltarra antretet. Sobald Ihr dort angelangt seid, sollt Ihr mit Erzmagier Berinand sprechen.", completion = "Willkommen in Kaltarra, {class}.\n\nHinter dem Transitusschild liegen wir verborgen, nur einen Steinwurf weit vom Nexus entfernt, der Festung des großen Aspekts Malygos und seinem blauen Drachenschwarm.\n\nFühlt Euch wie Zuhause.", sourceObjectiveStatus = "unverified-source-field" }
quests[11734] = { id = 11734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entweiht dieses Feuer!", sourceObjective = "Entweiht das Freudenfeuer der Allianz im Eschental!", sourceObjectiveStatus = "unverified-source-field" }
