quests[11863] = { id = 11863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", sourceObjective = "Ehrt die Flamme der Zangarmarschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11864] = { id = 11864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Missionsrichtlinie", sourceObjective = "Der Dämon hat viele Namen und jeder Name hat zur einen oder anderen Zeit eine besondere Bedeutung gehabt. Während die Einzelheiten eher unwichtig waren, war das Ergebnis immer dasselbe: der Tod.\n\nDoch nun, fast fünfzig Jahre nachdem alles begann, wird das Detail ausnahmsweise den Teufel einholen und zu seinem Untergang führen.\n\nDiesmal haben wir ihn... Es wird kein Entrinnen für Nesingwary geben.\n\nNordend wird als Schlachtfeld unseres Kampfes dienen. Der Jäger wird zum Gejagten!", sourceObjectiveStatus = "unverified-source-field" }
quests[11865] = { id = 11865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Todes unwürdig", description = "Gleich südlich von hier streiften einst Karibus frei und in Frieden umher. Doch dann kam Nesingwary und alles wurde anders. Nun befinden sich die Karibus in einem ständigen Zustand der Raserei und Panik. Sie werden von den im Feld versteckten Jägern und Fallenstellern gejagt.\n\nNesingwarys Henker sind nicht einmal des Todes würdig. Sie müssen dieselben Qualen erleiden, die sie den Karibus zufügen!\n\nNehmt diesen Haufen Kunstpelze und legt sie auf die Karibufallen, die im Süden aufgestellt sind. Beobachtet, wie die Jäger in ihre eigenen tödlichen Fallen tappen!", sourceObjective = "Zaza beim Lager der D.E.H.T.A. in der Boreanischen Tundra möchte, dass Ihr den Haufen Kunstpelze dazu verwendet, um 8 von Nesingwarys Fallenstellern in die Falle zu locken.", progress = "Habt kein Mitleid mit ihnen, {race}.", completion = "Ihr führt der Erdenmutter Arbeit aus, {name}, doch genießt Euren Sieg nicht allzu lange. Wir haben das Versteck des Anführers der Fallensteller entdeckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11866] = { id = 11866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ohren unserer Feinde", description = "Ob sie Schatzsucher sind oder blutrünstige Jäger der Steppe, jeder, der Nesingwary unterstützt und es wagt, gegen unsere geliebte Tierwelt vorzugehen, soll als Feind der D.E.H.T.A. betrachtet werden.\n\nSolltet Ihr diese dreckigen Sympathisanten von Nesingwary umbringen, bringt mir einen Beweis ihres Ablebens und Ihr sollt mit einem Segen der Druiden der D.E.H.T.A. belohnt werden.", sourceObjective = "Erzdruide Lathorius beim Lager der D.E.H.T.A. in der Boreanischen Tundra hat gesagt, dass er Euch belohnen wird, wenn Ihr ihm 15 Ohren von Nesingwarys Lakaien bringt.", progress = "Ohren erfüllen den Zweck doch sehr wohl...", completion = "Die werde ich mir um den Hals hängen. Lasst sie unsere Botschaft hören und lasst diese Ohren die Überbringer unserer Wahrheit sein!", sourceObjectiveStatus = "unverified-source-field" }
